(1, 'daily-greetings', 'lessonMeta', '{"id":"daily-greetings","title":{"en":"打招呼 / Daily greetings","fr":"打招呼 / Salutations quotidiennes"},"scenario":{"en":"How to say hello, goodbye and be polite.","fr":"Comment dire bonjour, au revoir et être poli."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(2, 'daily-greetings', 'lessonMeta', '{"id":"daily-greetings","title":{"en":"打招呼 / Daily greetings","fr":"打招呼 / Salutations quotidiennes"},"scenario":{"en":"How to say hello, goodbye and be polite.","fr":"Comment dire bonjour, au revoir et être poli."}}', 'draft', 1, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(3, 'daily-greetings', 'dialogue', '{"title":{"en":"Everyday greetings and polite phrases","fr":"Salutations et formules de politesse du quotidien"},"lines":[{"id":"daily-greetings-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好。","pinyin":"Nǐ hǎo.","translation":{"en":"Hello.","fr":"Bonjour."},"explanation":{"en":"你好 is the everyday greeting you can use with anyone your own age or in casual situations.","fr":"你好 est la salutation quotidienne à utiliser avec des personnes de votre âge ou en situation informelle."},"audio":"/audio/daily-greetings/line-01.mp3"},{"id":"daily-greetings-line-02","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"您好。","pinyin":"Nín hǎo.","translation":{"en":"Hello (formal).","fr":"Bonjour (formel)."},"explanation":{"en":"您好 is the polite form of hello, best for staff, elders, or anyone you want to show respect.","fr":"您好 est la forme polie de bonjour, idéale avec le personnel, les aînés ou pour montrer du respect."},"audio":"/audio/daily-greetings/line-02.mp3"},{"id":"daily-greetings-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"大家好。","pinyin":"Dàjiā hǎo.","translation":{"en":"Hello everyone.","fr":"Bonjour à tous."},"explanation":{"en":"Use 大家好 to greet a group of people at once.","fr":"Utilisez 大家好 pour saluer tout un groupe d’un coup."},"audio":"/audio/daily-greetings/line-03.mp3"},{"id":"daily-greetings-line-04","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"早上好。","pinyin":"Zǎoshang hǎo.","translation":{"en":"Good morning.","fr":"Bonjour (le matin)."},"explanation":{"en":"早上好 is the greeting to use in the morning, before around noon.","fr":"早上好 est la salutation du matin, à utiliser jusqu’à midi environ."},"audio":"/audio/daily-greetings/line-04.mp3"},{"id":"daily-greetings-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"下午好。","pinyin":"Xiàwǔ hǎo.","translation":{"en":"Good afternoon.","fr":"Bonjour (l’après-midi)."},"explanation":{"en":"下午好 is the polite greeting for the afternoon.","fr":"下午好 est la salutation polie de l’après-midi."},"audio":"/audio/daily-greetings/line-05.mp3"},{"id":"daily-greetings-line-06","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"晚上好。","pinyin":"Wǎnshang hǎo.","translation":{"en":"Good evening.","fr":"Bonsoir."},"explanation":{"en":"晚上好 is the greeting used in the evening when you meet someone.","fr":"晚上好 est la salutation utilisée le soir lorsque vous rencontrez quelqu’un."},"audio":"/audio/daily-greetings/line-06.mp3"},{"id":"daily-greetings-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"晚安。","pinyin":"Wǎn’ān.","translation":{"en":"Good night.","fr":"Bonne nuit."},"explanation":{"en":"晚安 is what you say when leaving or going to sleep at night.","fr":"晚安 se dit lorsque vous partez ou que vous allez dormir le soir."},"audio":"/audio/daily-greetings/line-07.mp3"},{"id":"daily-greetings-line-08","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好吗？","pinyin":"Nǐ hǎo ma?","translation":{"en":"How are you?","fr":"Comment allez-vous ?"},"explanation":{"en":"Add 吗 to a statement to turn it into a yes-or-no question.","fr":"Ajoutez 吗 à une phrase pour en faire une question à réponse oui ou non."},"audio":"/audio/daily-greetings/line-08.mp3"},{"id":"daily-greetings-line-09","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我很好，谢谢。","pinyin":"Wǒ hěn hǎo, xièxie.","translation":{"en":"I am very good, thank you.","fr":"Je vais très bien, merci."},"explanation":{"en":"我很好 replies that you are doing well, and 谢谢 adds thanks.","fr":"我很好 répond que tout va bien, et 谢谢 ajoute un merci."},"audio":"/audio/daily-greetings/line-09.mp3"},{"id":"daily-greetings-line-10","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"很高兴认识你。","pinyin":"Hěn gāoxìng rènshi nǐ.","translation":{"en":"Nice to meet you.","fr":"Enchanté de faire votre connaissance."},"explanation":{"en":"Say 很高兴认识你 when you meet someone for the first time.","fr":"Dites 很高兴认识你 lorsque vous rencontrez quelqu’un pour la première fois."},"audio":"/audio/daily-greetings/line-10.mp3"},{"id":"daily-greetings-line-11","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"谢谢。","pinyin":"Xièxie.","translation":{"en":"Thank you.","fr":"Merci."},"explanation":{"en":"谢谢 is the most useful polite word in any everyday exchange.","fr":"谢谢 est le mot de politesse le plus utile dans tout échange quotidien."},"audio":"/audio/daily-greetings/line-11.mp3"},{"id":"daily-greetings-line-12","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"不客气。","pinyin":"Bú kèqi.","translation":{"en":"You are welcome.","fr":"Je vous en prie."},"explanation":{"en":"不客气 is the standard reply when someone thanks you.","fr":"不客气 est la réponse standard quand quelqu’un vous remercie."},"audio":"/audio/daily-greetings/line-12.mp3"},{"id":"daily-greetings-line-13","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"不好意思。","pinyin":"Bù hǎoyìsi.","translation":{"en":"Excuse me.","fr":"Excusez-moi."},"explanation":{"en":"不好意思 politely gets someone’s attention or apologizes lightly.","fr":"不好意思 permet d’attirer poliment l’attention de quelqu’un ou de s’excuser légèrement."},"audio":"/audio/daily-greetings/line-13.mp3"},{"id":"daily-greetings-line-14","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"对不起。","pinyin":"Duìbuqǐ.","translation":{"en":"I’m sorry.","fr":"Je suis désolé."},"explanation":{"en":"对不起 is a sincere apology when you have made a mistake.","fr":"对不起 est une excuse sincère lorsque vous avez fait une erreur."},"audio":"/audio/daily-greetings/line-14.mp3"},{"id":"daily-greetings-line-15","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"是的。","pinyin":"Shì de.","translation":{"en":"Yes.","fr":"Oui."},"explanation":{"en":"是的 is a clear way to confirm or say yes.","fr":"是的 est une façon claire de confirmer ou de dire oui."},"audio":"/audio/daily-greetings/line-15.mp3"},{"id":"daily-greetings-line-16","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"不是。","pinyin":"Bú shì.","translation":{"en":"No.","fr":"Non."},"explanation":{"en":"不是 politely says no when something is not the case.","fr":"不是 dit poliment non lorsque quelque chose n’est pas le cas."},"audio":"/audio/daily-greetings/line-16.mp3"},{"id":"daily-greetings-line-17","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"再见。","pinyin":"Zàijiàn.","translation":{"en":"Goodbye.","fr":"Au revoir."},"explanation":{"en":"再见 is the everyday way to say goodbye when leaving.","fr":"再见 est la façon quotidienne de dire au revoir en partant."},"audio":"/audio/daily-greetings/line-17.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
