"/audio/daily-greetings/line-10.mp3"},{"id":"daily-greetings-line-11","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"谢谢。","pinyin":"Xièxie.","translation":{"en":"Thank you.","fr":"Merci."},"explanation":{"en":"谢谢 is the most useful polite word in any everyday exchange.","fr":"谢谢 est le mot de politesse le plus utile dans tout échange quotidien."},"audio":"/audio/daily-greetings/line-11.mp3"},{"id":"daily-greetings-line-12","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"不客气。","pinyin":"Bú kèqi.","translation":{"en":"You are welcome.","fr":"Je vous en prie."},"explanation":{"en":"不客气 is the standard reply when someone thanks you.","fr":"不客气 est la réponse standard quand quelqu’un vous remercie."},"audio":"/audio/daily-greetings/line-12.mp3"},{"id":"daily-greetings-line-13","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"不好意思。","pinyin":"Bù hǎoyìsi.","translation":{"en":"Excuse me.","fr":"Excusez-moi."},"explanation":{"en":"不好意思 politely gets someone’s attention or apologizes lightly.","fr":"不好意思 permet d’attirer poliment l’attention de quelqu’un ou de s’excuser légèrement."},"audio":"/audio/daily-greetings/line-13.mp3"},{"id":"daily-greetings-line-14","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"对不起。","pinyin":"Duìbuqǐ.","translation":{"en":"I’m sorry.","fr":"Je suis désolé."},"explanation":{"en":"对不起 is a sincere apology when you have made a mistake.","fr":"对不起 est une excuse sincère lorsque vous avez fait une erreur."},"audio":"/audio/daily-greetings/line-14.mp3"},{"id":"daily-greetings-line-15","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"是的。","pinyin":"Shì de.","translation":{"en":"Yes.","fr":"Oui."},"explanation":{"en":"是的 is a clear way to confirm or say yes.","fr":"是的 est une façon claire de confirmer ou de dire oui."},"audio":"/audio/daily-greetings/line-15.mp3"},{"id":"daily-greetings-line-16","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"不是。","pinyin":"Bú shì.","translation":{"en":"No.","fr":"Non."},"explanation":{"en":"不是 politely says no when something is not the case.","fr":"不是 dit poliment non lorsque quelque chose n’est pas le cas."},"audio":"/audio/daily-greetings/line-16.mp3"},{"id":"daily-greetings-line-17","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"再见。","pinyin":"Zàijiàn.","translation":{"en":"Goodbye.","fr":"Au revoir."},"explanation":{"en":"再见 is the everyday way to say goodbye when leaving.","fr":"再见 est la façon quotidienne de dire au revoir en partant."},"audio":"/audio/daily-greetings/line-17.mp3"}]}', 'draft', 3, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(5, 'daily-greetings', 'sentencePatterns', '[{"id":"daily-greetings-pattern-1","pattern":"你好，……","meaning":{"en":"Hello, ...","fr":"Bonjour, ..."},"example":"你好，早上好。","audio":"/audio/daily-greetings/pattern-01.mp3","explanation":{"en":"Combine 你好 with a time-of-day greeting to sound natural when you meet someone.","fr":"Combinez 你好 avec une salutation selon le moment de la journée pour être naturel."}},{"id":"daily-greetings-pattern-2","pattern":"……吗？","meaning":{"en":"Is it ...? / Do you ...?","fr":"Est-ce que ... ?"},"example":"你好吗？","audio":"/audio/daily-greetings/pattern-02.mp3","explanation":{"en":"Adding 吗 at the end turns a statement into a question.","fr":"Ajouter 吗 à la fin transforme une phrase en question."}},{"id":"daily-greetings-pattern-3","pattern":"我很……，谢谢。","meaning":{"en":"I am very ..., thank you.","fr":"Je suis très ..., merci."},"example":"我很好，谢谢。","audio":"/audio/daily-greetings/pattern-03.mp3","explanation":{"en":"Use 很 before an adjective to say you are doing very well.","fr":"Utilisez 很 avant un adjectif pour dire que tout va très bien."}},{"id":"daily-greetings-pattern-4","pattern":"很高兴……","meaning":{"en":"I am glad to ...","fr":"Je suis ravi de ..."},"example":"很高兴认识你。","audio":"/audio/daily-greetings/pattern-04.mp3","explanation":{"en":"Start with 很高兴 and add what you are glad about, like meeting someone.","fr":"Commencez par 很高兴 et ajoutez ce qui vous fait plaisir, comme rencontrer quelqu’un."}},{"id":"daily-greetings-pattern-5","pattern":"不好意思，……","meaning":{"en":"Excuse me, ...","fr":"Excusez-moi, ..."},"example":"不好意思，谢谢。","audio":"/audio/daily-greetings/pattern-05.mp3","explanation":{"en":"Start with 不好意思 to interrupt politely before the main point.","fr":"Commencez par 不好意思 pour interrompre poliment avant le point principal."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(6, 'daily-greetings', 'sentencePatterns', '[{"id":"daily-greetings-pattern-1","pattern":"你好，……","meaning":{"en":"Hello, ...","fr":"Bonjour, ..."},"example":"你好，早上好。","audio":"/audio/daily-greetings/pattern-01.mp3","explanation":{"en":"Combine 你好 with a time-of-day greeting to sound natural when you meet someone.","fr":"Combinez 你好 avec une salutation selon le moment de la journée pour être naturel."}},{"id":"daily-greetings-pattern-2","pattern":"……吗？","meaning":{"en":"Is it ...? / Do you ...?","fr":"Est-ce que ... ?"},"example":"你好吗？","audio":"/audio/daily-greetings/pattern-02.mp3","explanation":{"en":"Adding 吗 at the end turns a statement into a question.","fr":"Ajouter 吗 à la fin transforme une phrase en question."}},{"id":"daily-greetings-pattern-3","pattern":"我很……，谢谢。","meaning":{"en":"I am very ..., thank you.","fr":"Je suis très ..., merci."},"example":"我很好，谢谢。","audio":"/audio/daily-greetings/pattern-03.mp3","explanation":{"en":"Use 很 before an adjective to say you are doing very well.","fr":"Utilisez 很 avant un adjectif pour dire que tout va très bien."}},{"id":"daily-greetings-pattern-4","pattern":"很高兴……","meaning":{"en":"I am glad to ...","fr":"Je suis ravi de ..."},"example":"很高兴认识你。","audio":"/audio/daily-greetings/pattern-04.mp3","explanation":{"en":"Start with 很高兴 and add what you are glad about, like meeting someone.","fr":"Commencez par 很高兴 et ajoutez ce qui vous fait plaisir, comme rencontrer quelqu’un."}},{"id":"daily-greetings-pattern-5","pattern":"不好意思，……","meaning":{"en":"Excuse me, ...","fr":"Excusez-moi, ..."},"example":"不好意思，谢谢。","audio":"/audio/daily-greetings/pattern-05.mp3","explanation":{"en":"Start with 不好意思 to interrupt politely before the main point.","fr":"Commencez par 不好意思 pour interrompre poliment avant le point principal."}}]', 'draft', 5, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(7, 'daily-greetings', 'vocabulary', '[{"id":"daily-greetings-vocab-1","hanzi":"你好","pinyin":"nǐ hǎo","audio":"/audio/daily-greetings/vocab-01.mp3","meaning":{"en":"hello","fr":"bonjour"},"explanation":{"en":"The everyday greeting for casual situations.","fr":"La salutation quotidienne pour les situations informelles."}},{"id":"daily-greetings-vocab-2","hanzi":"您好","pinyin":"nín hǎo","audio":"/audio/daily-greetings/vocab-02.mp3","meaning":{"en":"hello (formal)","fr":"bonjour (formel)"},"explanation":{"en":"The polite greeting for staff and elders.","fr":"La salutation polie pour le personnel et les aînés."}},{"id":"daily-greetings-vocab-3","hanzi":"早上好","pinyin":"zǎoshang hǎo","audio":"/audio/daily-greetings/vocab-03.mp3","meaning":{"en":"good morning","fr":"bonjour (matin)"},"explanation":{"en":"Use this greeting in the morning.","fr":"Utilisez cette salutation le matin."}},{"id":"daily-greetings-vocab-4","hanzi":"晚安","pinyin":"wǎn’ān","audio":"/audio/daily-greetings/vocab-04.mp3","meaning":{"en":"good night","fr":"bonne nuit"},"explanation":{"en":"Say this when leaving at night.","fr":"Dites ceci en partant le soir."}},{"id":"daily-greetings-vocab-5","hanzi":"谢谢","pinyin":"xièxie","audio":"/audio/daily-greetings/vocab-05.mp3","meaning":{"en":"thank you","fr":"merci"},"explanation":{"en":"The most useful polite word every day.","fr":"Le mot de politesse le plus utile au quotidien."}},{"id":"daily-greetings-vocab-6","hanzi":"不客气","pinyin":"bú kèqi","audio":"/audio/daily-greetings/vocab-06.mp3","meaning":{"en":"you are welcome","fr":"je vous en prie"},"explanation":{"en":"The standard reply to thank you.","fr":"La réponse standard à merci."}},{"id":"daily-greetings-vocab-7","hanzi":"不好意思","pinyin":"bù hǎoyìsi","audio":"/audio/daily-greetings/vocab-07.mp3","meaning":{"en":"excuse me","fr":"excusez-moi"},"explanation":{"en":"A light apology or way to get attention.","fr":"Une excuse légère ou une façon d’attirer l’attention."}},{"id":"daily-greetings-vocab-8","hanzi":"对不起","pinyin":"duìbuqǐ","audio":"/audio/daily-greetings/vocab-08.mp3","meaning":{"en":"I’m sorry","fr":"je suis désolé"},"explanation":{"en":"A sincere apology after a mistake.","fr":"Une excuse sincère après une erreur."}},{"id":"daily-greetings-vocab-9","hanzi":"再见","pinyin":"zàijiàn","audio":"/audio/daily-greetings/vocab-09.mp3","meaning":{"en":"goodbye","fr":"au revoir"},"explanation":{"en":"The everyday word to say when leaving.","fr":"Le mot quotidien à dire en partant."}},{"id":"daily-greetings-vocab-10","hanzi":"认识","pinyin":"rènshi","audio":"/audio/daily-greetings/vocab-10.mp3","meaning":{"en":"to meet / to know","fr":"rencontrer / connaître"},"explanation":{"en":"Used in 很高兴认识你 when meeting someone new.","fr":"Utilisé dans 很高兴认识你 lorsqu’on rencontre quelqu’un de nouveau."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(8, 'daily-greetings', 'vocabulary', '[{"id":"daily-greetings-vocab-1","hanzi":"你好","pinyin":"nǐ hǎo","audio":"/audio/daily-greetings/vocab-01.mp3","meaning":{"en":"hello","fr":"bonjour"},"explanation":{"en":"The everyday greeting for casual situations.","fr":"La salutation quotidienne pour les situations informelles."}},{"id":"daily-greetings-vocab-2","hanzi":"您好","pinyin":"nín hǎo","audio":"/audio/daily-greetings/vocab-02.mp3","meaning":{"en":"hello (formal)","fr":"bonjour (formel)"},"explanation":{"en":"The polite greeting for staff and elders.","fr":"La salutation polie pour le personnel et les aînés."}},{"id":"daily-greetings-vocab-3","hanzi":"早上好","pinyin":"zǎoshang hǎo","audio":"/audio/daily-greetings/vocab-03.mp3","meaning":{"en":"good morning","fr":"bonjour (matin)"},"explanation":{"en":"Use this greeting in the morning.","fr":"Utilisez cette salutation le matin."}},{"id":"daily-greetings-vocab-4","hanzi":"晚安","pinyin":"wǎn’ān","audio":"/audio/daily-greetings/vocab-04.mp3","meaning":{"en":"good night","fr":"bonne nuit"},"explanation":{"en":"Say this when leaving at night.","fr":"Dites ceci en partant le soir."}},{"id":"daily-greetings-vocab-5","hanzi":"谢谢","pinyin":"xièxie","audio":"/audio/daily-greetings/vocab-05.mp3","meaning":{"en":"thank you","fr":"merci"},"explanation":{"en":"The most useful polite word every day.","fr":"Le mot de politesse le plus utile au quotidien."}},{"id":"daily-greetings-vocab-6","hanzi":"不客气","pinyin":"bú kèqi","audio":"/audio/daily-greetings/vocab-06.mp3","meaning":{"en":"you are welcome","fr":"je vous en prie"},"explanation":{"en":"The standard reply to thank you.","fr":"La réponse standard à merci."}},{"id":"daily-greetings-vocab-7","hanzi":"不好意思","pinyin":"bù hǎoyìsi","audio":"/audio/daily-greetings/vocab-07.mp3","meaning":{"en":"excuse me","fr":"excusez-moi"},"explanation":{"en":"A light apology or way to get attention.","fr":"Une excuse légère ou une façon d’attirer l’attention."}},{"id":"daily-greetings-vocab-8","hanzi":"对不起","pinyin":"duìbuqǐ","audio":"/audio/daily-greetings/vocab-08.mp3","meaning":{"en":"I’m sorry","fr":"je suis désolé"},"explanation":{"en":"A sincere apology after a mistake.","fr":"Une excuse sincère après une erreur."}},{"id":"daily-greetings-vocab-9","hanzi":"再见","pinyin":"zàijiàn","audio":"/audio/daily-greetings/vocab-09.mp3","meaning":{"en":"goodbye","fr":"au revoir"},"explanation":{"en":"The everyday word to say when leaving.","fr":"Le mot quotidien à dire en partant."}},{"id":"daily-greetings-vocab-10","hanzi":"认识","pinyin":"rènshi","audio":"/audio/daily-greetings/vocab-10.mp3","meaning":{"en":"to meet / to know","fr":"rencontrer / connaître"},"explanation":{"en":"Used in 很高兴认识你 when meeting someone new.","fr":"Utilisé dans 很高兴认识你 lorsqu’on rencontre quelqu’un de nouveau."}}]', 'draft', 7, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(9, 'daily-greetings', 'practice', '{"listening":[{"id":"daily-greetings-listening-1","prompt":{"en":"Which phrase means “Hello everyone”?","fr":"Quelle phrase signifie « Bonjour à tous » ?"},"target":"大家好。","pinyin":"Dàjiā hǎo.","audio":"/audio/daily-greetings/practice-listening-01.mp3","explanation":{"en":"大家好 greets a whole group at once.","fr":"大家好 salue tout un groupe d’un coup."}},{"id":"daily-greetings-listening-2","prompt":{"en":"Which phrase is the polite formal greeting?","fr":"Quelle phrase est la salutation formelle polie ?"},"target":"您好。","pinyin":"Nín hǎo.","audio":"/audio/daily-greetings/practice-listening-02.mp3","explanation":{"en":"您好 shows respect, perfect for staff and elders.","fr":"您好 montre du respect, parfait pour le personnel et les aînés."}}],"speaking":[{"id":"daily-greetings-speaking-1","prompt":{"en":"Say “Good morning” to someone you just met.","fr":"Dites « Bonjour » à quelqu’un que vous venez de rencontrer."},"target":"早上好。","pinyin":"Zǎoshang hǎo.","audio":"/audio/daily-greetings/practice-speaking-01.mp3","explanation":{"en":"Use 早上好 as the morning greeting.","fr":"Utilisez 早上好 comme salutation du matin."}},{"id":"daily-greetings-speaking-2","prompt":{"en":"Thank someone and reply when they are welcome.","fr":"Remerciez quelqu’un et répondez-lui poliment."},"target":"谢谢。不客气。","pinyin":"Xièxie. Bú kèqi.","audio":"/audio/daily-greetings/practice-speaking-02.mp3","explanation":{"en":"谢谢 thanks the other person and 不客气 is the reply.","fr":"谢谢 remercie l’autre personne et 不客气 est la réponse."}}],"reading":[{"id":"daily-greetings-reading-1","prompt":{"en":"Match the word to “thank you”.","fr":"Associe le mot à « merci »."},"target":"谢谢","pinyin":"xièxie","audio":"/audio/daily-greetings/practice-reading-01.mp3","explanation":{"en":"谢谢 is the word for thank you.","fr":"谢谢 est le mot pour merci."}},{"id":"daily-greetings-reading-2","prompt":{"en":"Match the word to “goodbye”.","fr":"Associe le mot à « au revoir »."},"target":"再见","pinyin":"zàijiàn","audio":"/audio/daily-greetings/practice-reading-02.mp3","explanation":{"en":"再见 is the everyday goodbye.","fr":"再见 est l’au revoir quotidien."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
