zàijiàn","audio":"/audio/daily-greetings/practice-reading-02.mp3","explanation":{"en":"再见 is the everyday goodbye.","fr":"再见 est l’au revoir quotidien."}}]}', 'draft', 9, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(11, 'daily-greetings', 'reviewCards', '[{"id":"daily-greetings-review-1","front":"你好","back":{"en":"hello","fr":"bonjour"},"explanation":{"en":"The everyday greeting.","fr":"La salutation quotidienne."}},{"id":"daily-greetings-review-2","front":"您好","back":{"en":"hello (formal)","fr":"bonjour (formel)"},"explanation":{"en":"The polite greeting for staff and elders.","fr":"La salutation polie pour le personnel et les aînés."}},{"id":"daily-greetings-review-3","front":"谢谢","back":{"en":"thank you","fr":"merci"},"explanation":{"en":"The most useful polite word.","fr":"Le mot de politesse le plus utile."}},{"id":"daily-greetings-review-4","front":"不客气","back":{"en":"you are welcome","fr":"je vous en prie"},"explanation":{"en":"The reply when someone thanks you.","fr":"La réponse quand quelqu’un vous remercie."}},{"id":"daily-greetings-review-5","front":"再见","back":{"en":"goodbye","fr":"au revoir"},"explanation":{"en":"Say this when leaving.","fr":"Dites ceci en partant."}},{"id":"daily-greetings-review-6","front":"对不起","back":{"en":"I’m sorry","fr":"je suis désolé"},"explanation":{"en":"A sincere apology.","fr":"Une excuse sincère."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
