(21, 'self-intro', 'practice', '{"listening":[{"id":"self-intro-listening-1","prompt":{"en":"Which sentence asks “Do you speak English?”?","fr":"Quelle phrase demande « Parlez-vous anglais ? » ?"},"target":"请问您会说英语吗？","pinyin":"Qǐngwèn nín huì shuō Yīngyǔ ma?","audio":"/audio/self-intro/practice-listening-01.mp3","explanation":{"en":"Use 请问您会说英语吗 when you need someone who can speak English.","fr":"Utilisez 请问您会说英语吗 quand vous avez besoin d’un anglophone."}},{"id":"self-intro-listening-2","prompt":{"en":"Which sentence asks where baggage claim is?","fr":"Quelle phrase demande où se trouve la récupération des bagages ?"},"target":"行李提取处在哪里？","pinyin":"Xíngli tíqǔchù zài nǎlǐ?","audio":"/audio/self-intro/practice-listening-02.mp3","explanation":{"en":"行李提取处在哪里 is the first thing to ask after landing.","fr":"行李提取处在哪里 est la première chose à demander après l’atterrissage."}}],"speaking":[{"id":"self-intro-speaking-1","prompt":{"en":"Say that you are here to travel.","fr":"Dites que vous venez pour le tourisme."},"target":"我是来旅游的。","pinyin":"Wǒ shì lái lǚyóu de.","audio":"/audio/self-intro/practice-speaking-01.mp3","explanation":{"en":"我是来旅游的 states your purpose for the trip.","fr":"我是来旅游的 indique le motif de votre voyage."}},{"id":"self-intro-speaking-2","prompt":{"en":"Ask where you can get a taxi.","fr":"Demandez où vous pouvez prendre un taxi."},"target":"请问去哪里打车？","pinyin":"Qǐngwèn qù nǎlǐ dǎchē?","audio":"/audio/self-intro/practice-speaking-02.mp3","explanation":{"en":"请问去哪里打车 asks the taxi pick-up location.","fr":"请问去哪里打车 demande l’emplacement des taxis."}}],"reading":[{"id":"self-intro-reading-1","prompt":{"en":"Match the airport sign word to “baggage claim”.","fr":"Associe le mot de l’aéroport à « récupération des bagages »."},"target":"行李提取处","pinyin":"xíngli tíqǔchù","audio":"/audio/self-intro/practice-reading-01.mp3","explanation":{"en":"行李提取处 is the sign to follow after landing.","fr":"行李提取处 est le panneau à suivre après l’atterrissage."}},{"id":"self-intro-reading-2","prompt":{"en":"Match the word to “subway”.","fr":"Associe le mot à « métro »."},"target":"地铁","pinyin":"dìtiě","audio":"/audio/self-intro/practice-reading-02.mp3","explanation":{"en":"地铁 is the subway, useful for city travel.","fr":"地铁 est le métro, utile pour les déplacements en ville."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
