eading-2","prompt":{"en":"Match the word to “subway”.","fr":"Associe le mot à « métro »."},"target":"地铁","pinyin":"dìtiě","audio":"/audio/self-intro/practice-reading-02.mp3","explanation":{"en":"地铁 is the subway, useful for city travel.","fr":"地铁 est le métro, utile pour les déplacements en ville."}}]}', 'draft', 21, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(23, 'self-intro', 'reviewCards', '[{"id":"self-intro-review-1","front":"护照","back":{"en":"passport","fr":"passeport"},"explanation":{"en":"The first document word to recognize after landing.","fr":"Le premier mot de document à reconnaître après l’atterrissage."}},{"id":"self-intro-review-2","front":"行李提取处","back":{"en":"baggage claim","fr":"récupération des bagages"},"explanation":{"en":"Where you collect your luggage.","fr":"L’endroit où récupérer vos bagages."}},{"id":"self-intro-review-3","front":"请问您会说英语吗","back":{"en":"Do you speak English?","fr":"Parlez-vous anglais ?"},"explanation":{"en":"A key rescue phrase when you need English help.","fr":"Une phrase de secours clé quand vous avez besoin d’aide en anglais."}},{"id":"self-intro-review-4","front":"我是来旅游的","back":{"en":"I’m here to travel.","fr":"Je viens pour le tourisme."},"explanation":{"en":"State your travel purpose at immigration.","fr":"Indiquez votre motif de voyage à l’immigration."}},{"id":"self-intro-review-5","front":"地铁","back":{"en":"subway / metro","fr":"métro"},"explanation":{"en":"The city transport you may use after the airport.","fr":"Le transport en ville après l’aéroport."}},{"id":"self-intro-review-6","front":"机场快线","back":{"en":"airport express","fr":"express de l’aéroport"},"explanation":{"en":"A fast train from the airport to the city.","fr":"Un train rapide de l’aéroport vers la ville."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
