(25, 'ask-directions', 'lessonMeta', '{"id":"ask-directions","title":{"en":"打车 / Take a taxi","fr":"打车 / Prendre un taxi"},"scenario":{"en":"Get to the right destination, ensure comfort and safety, make the payment.","fr":"Arriver à la bonne destination, assurer confort et sécurité, et régler la course."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(26, 'ask-directions', 'lessonMeta', '{"id":"ask-directions","title":{"en":"打车 / Take a taxi","fr":"打车 / Prendre un taxi"},"scenario":{"en":"Get to the right destination, ensure comfort and safety, make the payment.","fr":"Arriver à la bonne destination, assurer confort et sécurité, et régler la course."}}', 'draft', 25, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(27, 'ask-directions', 'dialogue', '{"title":{"en":"Tell the driver your destination","fr":"Indiquer sa destination au chauffeur"},"lines":[{"id":"ask-directions-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"师傅，去这个酒店。","pinyin":"Shīfu, qù zhège jiǔdiàn.","translation":{"en":"Driver, please go to this hotel.","fr":"Chauffeur, allez à cet hôtel, s''il vous plaît."},"explanation":{"en":"师傅 is a practical way to address a taxi driver politely.","fr":"师傅 est une façon pratique et polie de s''adresser à un chauffeur."},"audio":"/audio/ask-directions/line-01.mp3"},{"id":"ask-directions-line-02","speaker":{"en":"Driver","fr":"Chauffeur"},"hanzi":"好的，你给我看一下地址。","pinyin":"Hǎo de, nǐ gěi wǒ kàn yíxià dìzhǐ.","translation":{"en":"Okay, show me the address.","fr":"D''accord, montre-moi l''adresse."},"explanation":{"en":"给我看一下 is useful when the driver wants to see your phone or booking address.","fr":"给我看一下 est utile quand le chauffeur veut voir l''adresse sur ton téléphone ou ta réservation."},"audio":"/audio/ask-directions/line-02.mp3"},{"id":"ask-directions-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"在这里。","pinyin":"Zài zhèlǐ.","translation":{"en":"It is here.","fr":"C''est ici."},"explanation":{"en":"Use 在这里 while pointing to the address on your phone.","fr":"Utilise 在这里 en montrant l''adresse sur ton téléphone."},"audio":"/audio/ask-directions/line-03.mp3"},{"id":"ask-directions-line-04","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"请打表。","pinyin":"Qǐng dǎbiǎo.","translation":{"en":"Please use the meter.","fr":"Veuillez utiliser le compteur."},"explanation":{"en":"Say 请打表 when you get in to make sure the driver starts the meter.","fr":"Dis 请打表 en montant pour t''assurer que le chauffeur démarre le compteur."},"audio":"/audio/ask-directions/line-04.mp3"},{"id":"ask-directions-line-05","speaker":{"en":"Driver","fr":"Chauffeur"},"hanzi":"好的，打表。","pinyin":"Hǎo de, dǎbiǎo.","translation":{"en":"Okay, the meter is on.","fr":"D''accord, le compteur est allumé."},"explanation":{"en":"The driver confirms the meter is running.","fr":"Le chauffeur confirme que le compteur fonctionne."},"audio":"/audio/ask-directions/line-05.mp3"},{"id":"ask-directions-line-06","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"大概多久到？","pinyin":"Dàgài duōjiǔ dào?","translation":{"en":"About how long until we arrive?","fr":"Environ combien de temps pour arriver ?"},"explanation":{"en":"大概多久到 is a short way to ask the approximate travel time.","fr":"大概多久到 est une façon courte de demander la durée approximative du trajet."},"audio":"/audio/ask-directions/line-06.mp3"},{"id":"ask-directions-line-07","speaker":{"en":"Driver","fr":"Chauffeur"},"hanzi":"四十分钟左右。","pinyin":"Sìshí fēnzhōng zuǒyòu.","translation":{"en":"Around forty minutes.","fr":"Environ quarante minutes."},"explanation":{"en":"左右 means around or about, useful with time and price estimates.","fr":"左右 signifie environ ; c''est utile pour les durées et les prix approximatifs."},"audio":"/audio/ask-directions/line-07.mp3"},{"id":"ask-directions-line-08","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"多少钱？可以扫码吗？","pinyin":"Duōshǎo qián? Kěyǐ sǎomǎ ma?","translation":{"en":"How much? Can I scan to pay?","fr":"Combien ? Je peux scanner pour payer ?"},"explanation":{"en":"Ask 多少钱 for the fare, then 可以扫码吗 to check if QR payment is accepted.","fr":"Demande 多少钱 pour le prix, puis 可以扫码吗 pour vérifier si le paiement par QR est accepté."},"audio":"/audio/ask-directions/line-08.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
