(33, 'ask-directions', 'practice', '{"listening":[{"id":"ask-directions-listening-1","prompt":{"en":"Which phrase tells the driver the destination?","fr":"Quelle phrase indique la destination au chauffeur ?"},"target":"师傅，去这个酒店。","audio":"/audio/ask-directions/practice-listening-01.mp3","explanation":{"en":"This is the first taxi sentence to get moving from the airport.","fr":"C''est la première phrase de taxi pour partir de l''aéroport."}},{"id":"ask-directions-listening-2","prompt":{"en":"Which phrase asks to use the meter?","fr":"Quelle phrase demande d''utiliser le compteur ?"},"target":"请打表。","audio":"/audio/ask-directions/practice-listening-02.mp3","explanation":{"en":"请打表 is the key safety phrase before the taxi starts moving.","fr":"请打表 est la phrase de sécurité clé avant que le taxi ne démarre."}}],"speaking":[{"id":"ask-directions-speaking-1","prompt":{"en":"Tell the driver to go to this hotel.","fr":"Dis au chauffeur d''aller à cet hôtel."},"target":"师傅，去这个酒店。","audio":"/audio/ask-directions/practice-speaking-01.mp3","explanation":{"en":"You can swap 酒店 for 公寓 when going to an apartment.","fr":"Tu peux remplacer 酒店 par 公寓 si tu vas à un appartement."}},{"id":"ask-directions-speaking-2","prompt":{"en":"Ask the driver to use the meter.","fr":"Demande au chauffeur d''utiliser le compteur."},"target":"请打表。","audio":"/audio/ask-directions/practice-speaking-02.mp3","explanation":{"en":"A short 请 before an action keeps the request polite and simple.","fr":"Un 请 court avant une action garde la demande polie et simple."}}],"reading":[{"id":"ask-directions-reading-1","prompt":{"en":"Match the phrase that asks about travel time.","fr":"Associe la phrase qui demande la durée du trajet."},"target":"大概多久到？","audio":"/audio/ask-directions/practice-reading-01.mp3","explanation":{"en":"大概多久到 asks about the approximate arrival time.","fr":"大概多久到 demande l''heure ou la durée approximative d''arrivée."}},{"id":"ask-directions-reading-2","prompt":{"en":"Match the payment phrase.","fr":"Associe la phrase de paiement."},"target":"可以扫码吗？","audio":"/audio/ask-directions/practice-reading-02.mp3","explanation":{"en":"Recognize 扫码 as the scan-to-pay action.","fr":"Reconnais 扫码 comme l''action de scanner pour payer."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(34, 'ask-directions', 'practice', '{"listening":[{"id":"ask-directions-listening-1","prompt":{"en":"Which phrase tells the driver the destination?","fr":"Quelle phrase indique la destination au chauffeur ?"},"target":"师傅，去这个酒店。","audio":"/audio/ask-directions/practice-listening-01.mp3","explanation":{"en":"This is the first taxi sentence to get moving from the airport.","fr":"C''est la première phrase de taxi pour partir de l''aéroport."}},{"id":"ask-directions-listening-2","prompt":{"en":"Which phrase asks to use the meter?","fr":"Quelle phrase demande d''utiliser le compteur ?"},"target":"请打表。","audio":"/audio/ask-directions/practice-listening-02.mp3","explanation":{"en":"请打表 is the key safety phrase before the taxi starts moving.","fr":"请打表 est la phrase de sécurité clé avant que le taxi ne démarre."}}],"speaking":[{"id":"ask-directions-speaking-1","prompt":{"en":"Tell the driver to go to this hotel.","fr":"Dis au chauffeur d''aller à cet hôtel."},"target":"师傅，去这个酒店。","audio":"/audio/ask-directions/practice-speaking-01.mp3","explanation":{"en":"You can swap 酒店 for 公寓 when going to an apartment.","fr":"Tu peux remplacer 酒店 par 公寓 si tu vas à un appartement."}},{"id":"ask-directions-speaking-2","prompt":{"en":"Ask the driver to use the meter.","fr":"Demande au chauffeur d''utiliser le compteur."},"target":"请打表。","audio":"/audio/ask-directions/practice-speaking-02.mp3","explanation":{"en":"A short 请 before an action keeps the request polite and simple.","fr":"Un 请 court avant une action garde la demande polie et simple."}}],"reading":[{"id":"ask-directions-reading-1","prompt":{"en":"Match the phrase that asks about travel time.","fr":"Associe la phrase qui demande la durée du trajet."},"target":"大概多久到？","audio":"/audio/ask-directions/practice-reading-01.mp3","explanation":{"en":"大概多久到 asks about the approximate arrival time.","fr":"大概多久到 demande l''heure ou la durée approximative d''arrivée."}},{"id":"ask-directions-reading-2","prompt":{"en":"Match the payment phrase.","fr":"Associe la phrase de paiement."},"target":"可以扫码吗？","audio":"/audio/ask-directions/practice-reading-02.mp3","explanation":{"en":"Recognize 扫码 as the scan-to-pay action.","fr":"Reconnais 扫码 comme l''action de scanner pour payer."}}]}', 'draft', 33, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(35, 'ask-directions', 'reviewCards', '[{"id":"ask-directions-review-1","front":"去这个酒店","back":{"en":"Go to this hotel.","fr":"Allez à cet hôtel."},"explanation":{"en":"Use it while showing the hotel on your phone.","fr":"Utilise-le en montrant l''hôtel sur ton téléphone."}},{"id":"ask-directions-review-2","front":"地址","back":{"en":"address","fr":"adresse"},"explanation":{"en":"A key word when confirming the destination.","fr":"Un mot clé pour confirmer la destination."}},{"id":"ask-directions-review-3","front":"大概多久到","back":{"en":"About how long until we arrive?","fr":"Environ combien de temps pour arriver ?"},"explanation":{"en":"Ask this when you want a rough travel-time estimate.","fr":"Pose cette question pour obtenir une estimation de durée."}},{"id":"ask-directions-review-4","front":"打表","back":{"en":"use the meter","fr":"utiliser le compteur"},"explanation":{"en":"A key taxi safety word.","fr":"Un mot clé de sécurité en taxi."}},{"id":"ask-directions-review-5","front":"扫码","back":{"en":"scan to pay","fr":"scanner pour payer"},"explanation":{"en":"The main way to pay in China.","fr":"Le principal moyen de payer en Chine."}},{"id":"ask-directions-review-6","front":"发票","back":{"en":"receipt / invoice","fr":"reçu / facture"},"explanation":{"en":"Ask for this if you need proof of payment.","fr":"Demande ceci si tu as besoin d''une preuve de paiement."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
