audio/order-food/practice-reading-02.mp3","explanation":{"en":"押金 is the deposit you may need to pay at check-in.","fr":"押金 est la caution que tu pourrais devoir payer au check-in."}}]}', 'draft', 45, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(47, 'order-food', 'reviewCards', '[{"id":"order-food-review-1","front":"我有预订","back":{"en":"I have a reservation.","fr":"J''ai une réservation."},"explanation":{"en":"Your opening sentence at the front desk.","fr":"Ta phrase d''ouverture à la réception."}},{"id":"order-food-review-2","front":"请出示护照","back":{"en":"Please show your passport.","fr":"Veuillez présenter votre passeport."},"explanation":{"en":"A common request during check-in.","fr":"Une demande courante pendant le check-in."}},{"id":"order-food-review-3","front":"房卡","back":{"en":"room card","fr":"carte de chambre"},"explanation":{"en":"The key card for your hotel room.","fr":"La carte clé de ta chambre d''hôtel."}},{"id":"order-food-review-4","front":"WiFi密码","back":{"en":"WiFi password","fr":"mot de passe WiFi"},"explanation":{"en":"Ask this right after check-in.","fr":"Demande ceci juste après le check-in."}},{"id":"order-food-review-5","front":"退房","back":{"en":"check out","fr":"check-out"},"explanation":{"en":"Know your checkout time.","fr":"Connais ton heure de check-out."}},{"id":"order-food-review-6","front":"押金","back":{"en":"deposit","fr":"caution"},"explanation":{"en":"You may need to pay this at the front desk.","fr":"Tu pourrais devoir payer ceci à la réception."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(48, 'order-food', 'reviewCards', '[{"id":"order-food-review-1","front":"我有预订","back":{"en":"I have a reservation.","fr":"J''ai une réservation."},"explanation":{"en":"Your opening sentence at the front desk.","fr":"Ta phrase d''ouverture à la réception."}},{"id":"order-food-review-2","front":"请出示护照","back":{"en":"Please show your passport.","fr":"Veuillez présenter votre passeport."},"explanation":{"en":"A common request during check-in.","fr":"Une demande courante pendant le check-in."}},{"id":"order-food-review-3","front":"房卡","back":{"en":"room card","fr":"carte de chambre"},"explanation":{"en":"The key card for your hotel room.","fr":"La carte clé de ta chambre d''hôtel."}},{"id":"order-food-review-4","front":"WiFi密码","back":{"en":"WiFi password","fr":"mot de passe WiFi"},"explanation":{"en":"Ask this right after check-in.","fr":"Demande ceci juste après le check-in."}},{"id":"order-food-review-5","front":"退房","back":{"en":"check out","fr":"check-out"},"explanation":{"en":"Know your checkout time.","fr":"Connais ton heure de check-out."}},{"id":"order-food-review-6","front":"押金","back":{"en":"deposit","fr":"caution"},"explanation":{"en":"You may need to pay this at the front desk.","fr":"Tu pourrais devoir payer ceci à la réception."}}]', 'draft', 47, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(49, 'phone-and-payment', 'lessonMeta', '{"id":"phone-and-payment","title":{"en":"中国电话卡 / SIM card setup","fr":"中国电话卡 / Configuration de la carte SIM"},"scenario":{"en":"Ask for a SIM card, set it up, buy data plan and top up.","fr":"Demander une carte SIM, la configurer, acheter un forfait data et recharger."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(50, 'phone-and-payment', 'lessonMeta', '{"id":"phone-and-payment","title":{"en":"中国电话卡 / SIM card setup","fr":"中国电话卡 / Configuration de la carte SIM"},"scenario":{"en":"Ask for a SIM card, set it up, buy data plan and top up.","fr":"Demander une carte SIM, la configurer, acheter un forfait data et recharger."}}', 'draft', 49, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(51, 'phone-and-payment', 'dialogue', '{"title":{"en":"Ask about phone and payment setup","fr":"Demander de l''aide pour le téléphone et le paiement"},"lines":[{"id":"phone-and-payment-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，我想办一张手机卡。","pinyin":"Nǐ hǎo, wǒ xiǎng bàn yì zhāng shǒujīkǎ.","translation":{"en":"Hello, I would like to get a SIM card.","fr":"Bonjour, je voudrais prendre une carte SIM."},"explanation":{"en":"我想办一张手机卡 keeps the request short and practical after check-in.","fr":"我想办一张手机卡 garde la demande courte et pratique après l''arrivée au logement."},"audio":"/audio/phone-and-payment/line-01.mp3"},{"id":"phone-and-payment-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"好的，请出示护照。","pinyin":"Hǎo de, qǐng chūshì hùzhào.","translation":{"en":"Okay, please show your passport.","fr":"D''accord, veuillez présenter votre passeport."},"explanation":{"en":"This reuses the passport phrase from arrival in a phone setup context.","fr":"Cette phrase réutilise le mot passeport dans un contexte de téléphone."},"audio":"/audio/phone-and-payment/line-02.mp3"},{"id":"phone-and-payment-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"这个号码可以用来支付吗？","pinyin":"Zhège hàomǎ kěyǐ yòng lái zhīfù ma?","translation":{"en":"Can this number be used for payment?","fr":"Est-ce que ce numéro peut servir au paiement ?"},"explanation":{"en":"The learner hears 手机号码 and 支付 as a simple setup question, not a full payment guide.","fr":"L''apprenant entend 手机号码 et 支付 dans une question simple, sans guide complet de paiement."},"audio":"/audio/phone-and-payment/line-03.mp3"},{"id":"phone-and-payment-line-04","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"可以，也可以先用现金。","pinyin":"Kěyǐ, yě kěyǐ xiān yòng xiànjīn.","translation":{"en":"Yes, and you can also use cash first.","fr":"Oui, et vous pouvez aussi utiliser des espèces d''abord."},"explanation":{"en":"现金 gives a safe fallback word if phone payment is not ready yet.","fr":"现金 donne un mot de secours si le paiement mobile n''est pas encore prêt."},"audio":"/audio/phone-and-payment/line-04.mp3"},{"id":"phone-and-payment-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"有什么流量套餐？","pinyin":"Yǒu shénme liúliàng tàocān?","translation":{"en":"What data plans do you have?","fr":"Quels forfaits data avez-vous ?"},"explanation":{"en":"Ask 有什么流量套餐 to compare data plan options at a phone shop.","fr":"Demande 有什么流量套餐 pour comparer les forfaits data dans une boutique."},"audio":"/audio/phone-and-payment/line-05.mp3"},{"id":"phone-and-payment-line-06","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"有10G和30G的，你要哪个？","pinyin":"Yǒu shí G hé sānshí G de, nǐ yào nǎge?","translation":{"en":"We have 10G and 30G. Which one do you want?","fr":"Nous avons 10 Go et 30 Go. Lequel voulez-vous ?"},"explanation":{"en":"The clerk names two plan sizes and asks you to choose.","fr":"L''employé nomme deux tailles de forfait et te demande de choisir."},"audio":"/audio/phone-and-payment/line-06.mp3"},{"id":"phone-and-payment-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"怎么充值？","pinyin":"Zěnme chōngzhí?","translation":{"en":"How do I top up?","fr":"Comment recharger ?"},"explanation":{"en":"Ask 怎么充值 to learn how to add credit to your phone.","fr":"Demande 怎么充值 pour savoir comment ajouter du crédit à ton téléphone."},"audio":"/audio/phone-and-payment/line-07.mp3"},{"id":"phone-and-payment-line-08","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"好的，谢谢。","pinyin":"Hǎo de, xièxie.","translation":{"en":"Okay, thank you.","fr":"D''accord, merci."},"explanation":{"en":"A short closing phrase keeps the exchange beginner friendly.","fr":"Une formule de clôture courte garde l''échange accessible aux débutants."},"audio":"/audio/phone-and-payment/line-08.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(52, 'phone-and-payment', 'dialogue', '{"title":{"en":"Ask about phone and payment setup","fr":"Demander de l''aide pour le téléphone et le paiement"},"lines":[{"id":"phone-and-payment-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，我想办一张手机卡。","pinyin":"Nǐ hǎo, wǒ xiǎng bàn yì zhāng shǒujīkǎ.","translation":{"en":"Hello, I would like to get a SIM card.","fr":"Bonjour, je voudrais prendre une carte SIM."},"explanation":{"en":"我想办一张手机卡 keeps the request short and practical after check-in.","fr":"我想办一张手机卡 garde la demande courte et pratique après l''arrivée au logement."},"audio":"/audio/phone-and-payment/line-01.mp3"},{"id":"phone-and-payment-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"好的，请出示护照。","pinyin":"Hǎo de, qǐng chūshì hùzhào.","translation":{"en":"Okay, please show your passport.","fr":"D''accord, veuillez présenter votre passeport."},"explanation":{"en":"This reuses the passport phrase from arrival in a phone setup context.","fr":"Cette phrase réutilise le mot passeport dans un contexte de téléphone."},"audio":"/audio/phone-and-payment/line-02.mp3"},{"id":"phone-and-payment-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"这个号码可以用来支付吗？","pinyin":"Zhège hàomǎ kěyǐ yòng lái zhīfù ma?","translation":{"en":"Can this number be used for payment?","fr":"Est-ce que ce numéro peut servir au paiement ?"},"explanation":{"en":"The learner hears 手机号码 and 支付 as a simple setup question, not a full payment guide.","fr":"L''apprenant entend 手机号码 et 支付 dans une question simple, sans guide complet de paiement."},"audio":"/audio/phone-and-payment/line-03.mp3"},{"id":"phone-and-payment-line-04","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"可以，也可以先用现金。","pinyin":"Kěyǐ, yě kěyǐ xiān yòng xiànjīn.","translation":{"en":"Yes, and you can also use cash first.","fr":"Oui, et vous pouvez aussi utiliser des espèces d''abord."},"explanation":{"en":"现金 gives a safe fallback word if phone payment is not ready yet.","fr":"现金 donne un mot de secours si le paiement mobile n''est pas encore prêt."},"audio":"/audio/phone-and-payment/line-04.mp3"},{"id":"phone-and-payment-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"有什么流量套餐？","pinyin":"Yǒu shénme liúliàng tàocān?","translation":{"en":"What data plans do you have?","fr":"Quels forfaits data avez-vous ?"},"explanation":{"en":"Ask 有什么流量套餐 to compare data plan options at a phone shop.","fr":"Demande 有什么流量套餐 pour comparer les forfaits data dans une boutique."},"audio":"/audio/phone-and-payment/line-05.mp3"},{"id":"phone-and-payment-line-06","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"有10G和30G的，你要哪个？","pinyin":"Yǒu shí G hé sānshí G de, nǐ yào nǎge?","translation":{"en":"We have 10G and 30G. Which one do you want?","fr":"Nous avons 10 Go et 30 Go. Lequel voulez-vous ?"},"explanation":{"en":"The clerk names two plan sizes and asks you to choose.","fr":"L''employé nomme deux tailles de forfait et te demande de choisir."},"audio":"/audio/phone-and-payment/line-06.mp3"},{"id":"phone-and-payment-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"怎么充值？","pinyin":"Zěnme chōngzhí?","translation":{"en":"How do I top up?","fr":"Comment recharger ?"},"explanation":{"en":"Ask 怎么充值 to learn how to add credit to your phone.","fr":"Demande 怎么充值 pour savoir comment ajouter du crédit à ton téléphone."},"audio":"/audio/phone-and-payment/line-07.mp3"},{"id":"phone-and-payment-line-08","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"好的，谢谢。","pinyin":"Hǎo de, xièxie.","translation":{"en":"Okay, thank you.","fr":"D''accord, merci."},"explanation":{"en":"A short closing phrase keeps the exchange beginner friendly.","fr":"Une formule de clôture courte garde l''échange accessible aux débutants."},"audio":"/audio/phone-and-payment/line-08.mp3"}]}', 'draft', 51, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(53, 'phone-and-payment', 'sentencePatterns', '[{"id":"phone-and-payment-pattern-1","pattern":"我要买一个……。","meaning":{"en":"I want to buy a ...","fr":"Je veux acheter un / une ..."},"example":"我要买一个 SIM 卡。","audio":"/audio/phone-and-payment/pattern-01.mp3","explanation":{"en":"Start the SIM card request with 我要买一个 SIM 卡.","fr":"Commence la demande de carte SIM avec 我要买一个 SIM 卡."}},{"id":"phone-and-payment-pattern-2","pattern":"能帮我……吗？","meaning":{"en":"Could you help me ...?","fr":"Pouvez-vous m''aider à ... ?"},"example":"能帮我安装一下吗？","audio":"/audio/phone-and-payment/pattern-02.mp3","explanation":{"en":"Use 能帮我…吗 to ask for help installing or setting something up.","fr":"Utilise 能帮我…吗 pour demander de l''aide pour installer ou configurer quelque chose."}},{"id":"phone-and-payment-pattern-3","pattern":"我需要……。","meaning":{"en":"I need ...","fr":"J''ai besoin de ..."},"example":"我需要流量。","audio":"/audio/phone-and-payment/pattern-03.mp3","explanation":{"en":"Say 我需要流量 to ask for mobile data.","fr":"Dis 我需要流量 pour demander de la data mobile."}},{"id":"phone-and-payment-pattern-4","pattern":"……有多少流量？","meaning":{"en":"How much data does ... have?","fr":"Combien de data a ... ?"},"example":"这个套餐有多少流量？","audio":"/audio/phone-and-payment/pattern-04.mp3","explanation":{"en":"Ask about the data allowance of a plan with 有多少流量.","fr":"Demande le volume de data d''un forfait avec 有多少流量."}},{"id":"phone-and-payment-pattern-5","pattern":"怎么……？","meaning":{"en":"How do I ...?","fr":"Comment ... ?"},"example":"怎么充值？","audio":"/audio/phone-and-payment/pattern-05.mp3","explanation":{"en":"Use 怎么 before a verb to ask how to do something, like 充值.","fr":"Utilise 怎么 avant un verbe pour demander comment faire quelque chose, comme 充值."}},{"id":"phone-and-payment-pattern-6","pattern":"多少钱？","meaning":{"en":"How much is it?","fr":"Combien ça coûte ?"},"example":"多少钱？","audio":"/audio/phone-and-payment/pattern-06.mp3","explanation":{"en":"Ask 多少钱 to get the price of a SIM card or data plan.","fr":"Demande 多少钱 pour connaître le prix d''une carte SIM ou d''un forfait."}},{"id":"phone-and-payment-pattern-7","pattern":"帮我设置一下网络好吗？","meaning":{"en":"Could you help me set up the Internet?","fr":"Pouvez-vous m''aider à configurer Internet ?"},"example":"帮我设置一下网络好吗？","audio":"/audio/phone-and-payment/pattern-07.mp3","explanation":{"en":"Use 帮我设置一下 to ask for help setting up a network or phone.","fr":"Utilise 帮我设置一下 pour demander de l''aide pour configurer un réseau ou un téléphone."}},{"id":"phone-and-payment-pattern-8","pattern":"没有网络。","meaning":{"en":"There is no internet.","fr":"Il n''y a pas de connexion Internet."},"example":"没有网络。","audio":"/audio/phone-and-payment/pattern-08.mp3","explanation":{"en":"Say 没有网络 to explain you have no internet connection.","fr":"Dis 没有网络 pour expliquer que tu n''as pas de connexion Internet."}},{"id":"phone-and-payment-pattern-9","pattern":"没有信号。","meaning":{"en":"There is no signal.","fr":"Il n''y a pas de signal."},"example":"没有信号。","audio":"/audio/phone-and-payment/pattern-09.mp3","explanation":{"en":"Say 没有信号 when your phone shows no network signal.","fr":"Dis 没有信号 quand ton téléphone n''affiche aucun signal."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
