(57, 'phone-and-payment', 'practice', '{"listening":[{"id":"phone-and-payment-listening-1","prompt":{"en":"Listen for the word that means SIM card.","fr":"Écoute le mot qui signifie carte SIM."},"target":"手机卡","audio":"/audio/phone-and-payment/practice-listening-01.mp3","explanation":{"en":"手机卡 is the phone card or SIM card in this service exchange.","fr":"手机卡 désigne la carte SIM dans cet échange de service."}},{"id":"phone-and-payment-listening-2","prompt":{"en":"Which phrase asks about data plans?","fr":"Quelle phrase demande les forfaits data ?"},"target":"有什么流量套餐？","audio":"/audio/phone-and-payment/practice-listening-02.mp3","explanation":{"en":"有什么流量套餐 helps you compare phone plan options.","fr":"有什么流量套餐 t''aide à comparer les forfaits téléphoniques."}}],"speaking":[{"id":"phone-and-payment-speaking-1","prompt":{"en":"Ask whether phone payment is possible.","fr":"Demande si le paiement par téléphone est possible."},"target":"可以用手机支付吗？","audio":"/audio/phone-and-payment/practice-speaking-01.mp3","explanation":{"en":"This question is the safest short way to check mobile payment.","fr":"Cette question est la manière courte la plus sûre de vérifier le paiement mobile."}},{"id":"phone-and-payment-speaking-2","prompt":{"en":"Ask how to top up your phone.","fr":"Demande comment recharger ton téléphone."},"target":"怎么充值？","audio":"/audio/phone-and-payment/practice-speaking-02.mp3","explanation":{"en":"怎么充值 is the fastest way to ask about adding credit.","fr":"怎么充值 est la façon la plus rapide de demander comment ajouter du crédit."}}],"reading":[{"id":"phone-and-payment-reading-1","prompt":{"en":"Match 手机号码 with its meaning.","fr":"Associe 手机号码 à son sens."},"target":"手机号码","audio":"/audio/phone-and-payment/practice-reading-01.mp3","explanation":{"en":"手机号码 means phone number.","fr":"手机号码 signifie numéro de téléphone."}},{"id":"phone-and-payment-reading-2","prompt":{"en":"Match the payment app name.","fr":"Associe le nom de l''appli de paiement."},"target":"微信","audio":"/audio/phone-and-payment/practice-reading-02.mp3","explanation":{"en":"微信 is the most important app name to recognize in China.","fr":"微信 est le nom d''application le plus important à reconnaître en Chine."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
