(60, 'phone-and-payment', 'reviewCards', '[{"id":"phone-and-payment-review-1","front":"手机卡","back":{"en":"SIM card / phone card","fr":"carte SIM / carte de téléphone"},"explanation":{"en":"Use this when asking for basic phone service.","fr":"Utilise ce mot pour demander un service téléphonique de base."}},{"id":"phone-and-payment-review-2","front":"手机号码","back":{"en":"phone number","fr":"numéro de téléphone"},"explanation":{"en":"This is the number attached to the phone or SIM card.","fr":"C''est le numéro lié au téléphone ou à la carte SIM."}},{"id":"phone-and-payment-review-3","front":"可以用手机支付吗？","back":{"en":"Can I pay by phone?","fr":"Puis-je payer avec mon téléphone ?"},"explanation":{"en":"A short practical question for shops and counters.","fr":"Une question courte et pratique dans les magasins et aux comptoirs."}},{"id":"phone-and-payment-review-4","front":"流量","back":{"en":"mobile data","fr":"données mobiles"},"explanation":{"en":"The word for mobile data.","fr":"Le mot pour les données mobiles."}},{"id":"phone-and-payment-review-5","front":"充值","back":{"en":"top up / recharge","fr":"recharger"},"explanation":{"en":"How to add credit to your phone.","fr":"Comment ajouter du crédit à ton téléphone."}},{"id":"phone-and-payment-review-6","front":"微信","back":{"en":"WeChat","fr":"WeChat"},"explanation":{"en":"The essential messaging and payment app.","fr":"L''application essentielle de messagerie et de paiement."}}]', 'draft', 59, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(61, 'restaurant-order', 'lessonMeta', '{"id":"restaurant-order","title":{"en":"点餐 / Order a meal","fr":"点餐 / Commander un repas"},"scenario":{"en":"Ask for a menu, order food and drinks, specify your preference and make the payment.","fr":"Demander un menu, commander plats et boissons, préciser sa préférence et régler l''addition."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(62, 'restaurant-order', 'lessonMeta', '{"id":"restaurant-order","title":{"en":"点餐 / Order a meal","fr":"点餐 / Commander un repas"},"scenario":{"en":"Ask for a menu, order food and drinks, specify your preference and make the payment.","fr":"Demander un menu, commander plats et boissons, préciser sa préférence et régler l''addition."}}', 'draft', 61, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(63, 'restaurant-order', 'dialogue', '{"title":{"en":"Order noodles in a small restaurant","fr":"Commander des nouilles dans un petit restaurant"},"lines":[{"id":"restaurant-order-line-01","speaker":{"en":"Customer","fr":"Client"},"hanzi":"你好，有菜单吗？","pinyin":"Nǐ hǎo, yǒu càidān ma?","translation":{"en":"Hello, do you have a menu?","fr":"Bonjour, avez-vous un menu ?"},"explanation":{"en":"有……吗 asks whether something is available before you order.","fr":"有……吗 sert à demander si quelque chose est disponible avant de commander."},"audio":"/audio/restaurant-order/line-01.mp3"},{"id":"restaurant-order-line-02","speaker":{"en":"Server","fr":"Serveur"},"hanzi":"有，这是菜单。","pinyin":"Yǒu, zhè shì càidān.","translation":{"en":"Yes, here is the menu.","fr":"Oui, voici le menu."},"explanation":{"en":"这是菜单 is a short handoff phrase you may hear at a restaurant.","fr":"这是菜单 est une phrase courte que tu peux entendre au restaurant."},"audio":"/audio/restaurant-order/line-02.mp3"},{"id":"restaurant-order-line-03","speaker":{"en":"Customer","fr":"Client"},"hanzi":"我要一碗牛肉面，不要辣。","pinyin":"Wǒ yào yì wǎn niúròu miàn, bú yào là.","translation":{"en":"I want one bowl of beef noodles, not spicy.","fr":"Je voudrais un bol de nouilles au bœuf, sans piment."},"explanation":{"en":"我要一碗 names one bowl; 不要辣 makes the safety preference clear.","fr":"我要一碗 indique un bol ; 不要辣 précise clairement la préférence sans piment."},"audio":"/audio/restaurant-order/line-03.mp3"},{"id":"restaurant-order-line-04","speaker":{"en":"Customer","fr":"Client"},"hanzi":"还要一杯水和筷子。","pinyin":"Hái yào yì bēi shuǐ hé kuàizi.","translation":{"en":"I also want a cup of water and chopsticks.","fr":"Je voudrais aussi un verre d''eau et des baguettes."},"explanation":{"en":"This keeps the extra request short: water plus chopsticks.","fr":"La demande supplémentaire reste courte : de l''eau et des baguettes."},"audio":"/audio/restaurant-order/line-04.mp3"},{"id":"restaurant-order-line-05","speaker":{"en":"Customer","fr":"Client"},"hanzi":"一共多少钱？","pinyin":"Yígòng duōshao qián?","translation":{"en":"How much is it altogether?","fr":"Combien ça fait au total ?"},"explanation":{"en":"Reuse 一共多少钱 when you are ready to pay.","fr":"Réutilise 一共多少钱 quand tu es prêt à payer."},"audio":"/audio/restaurant-order/line-05.mp3"},{"id":"restaurant-order-line-06","speaker":{"en":"Server","fr":"Serveur"},"hanzi":"大份还是小份？","pinyin":"Dà fèn háishì xiǎo fèn?","translation":{"en":"Large or small portion?","fr":"Grande ou petite portion ?"},"explanation":{"en":"大份还是小份 is a common question about portion size in small restaurants.","fr":"大份还是小份 est une question courante sur la taille des portions dans les petits restaurants."},"audio":"/audio/restaurant-order/line-06.mp3"},{"id":"restaurant-order-line-07","speaker":{"en":"Customer","fr":"Client"},"hanzi":"小份。还有可乐吗？","pinyin":"Xiǎo fèn. Hái yǒu kělè ma?","translation":{"en":"Small portion. And do you have cola?","fr":"Petite portion. Et avez-vous du cola ?"},"explanation":{"en":"Confirm the size, then use 还有…吗 to ask about a drink.","fr":"Confirme la taille, puis utilise 还有…吗 pour demander une boisson."},"audio":"/audio/restaurant-order/line-07.mp3"},{"id":"restaurant-order-line-08","speaker":{"en":"Server","fr":"Serveur"},"hanzi":"可以。在这儿吃还是带走？","pinyin":"Kěyǐ. Zài zhèr chī háishì dàizǒu?","translation":{"en":"Sure. Eat here or take away?","fr":"D''accord. Sur place ou à emporter ?"},"explanation":{"en":"在这儿吃 means eat here; 带走 means take away.","fr":"在这儿吃 signifie manger sur place ; 带走 signifie à emporter."},"audio":"/audio/restaurant-order/line-08.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
