n."}},{"id":"restaurant-order-vocab-8","hanzi":"可乐","pinyin":"kělè","audio":"/audio/restaurant-order/vocab-08.mp3","meaning":{"en":"cola","fr":"cola"},"explanation":{"en":"A common drink to order in restaurants.","fr":"Une boisson courante à commander au restaurant."}},{"id":"restaurant-order-vocab-9","hanzi":"带走","pinyin":"dàizǒu","audio":"/audio/restaurant-order/vocab-09.mp3","meaning":{"en":"take away","fr":"à emporter"},"explanation":{"en":"Use it when you want to take the food with you.","fr":"Utilise-le quand tu veux emporter la nourriture."}},{"id":"restaurant-order-vocab-10","hanzi":"买单","pinyin":"mǎidān","audio":"/audio/restaurant-order/vocab-10.mp3","meaning":{"en":"pay the bill","fr":"payer l''addition"},"explanation":{"en":"Say 买单 to ask for the bill at the end of a meal.","fr":"Dis 买单 pour demander l''addition à la fin du repas."}}]', 'draft', 67, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(69, 'restaurant-order', 'practice', '{"listening":[{"id":"restaurant-order-listening-1","prompt":{"en":"Listen for the request to see the menu and order beef noodles.","fr":"Écoute la demande du menu et la commande de nouilles au bœuf."},"target":"有菜单吗？我要一碗牛肉面。","audio":"/audio/restaurant-order/practice-listening-01.mp3","explanation":{"en":"The target combines the menu question with a simple food order.","fr":"La cible combine la question du menu avec une commande simple."}},{"id":"restaurant-order-listening-2","prompt":{"en":"Which phrase means take away?","fr":"Quelle phrase signifie à emporter ?"},"target":"带走","audio":"/audio/restaurant-order/practice-listening-02.mp3","explanation":{"en":"带走 is the word for taking food to go.","fr":"带走 est le mot pour emporter la nourriture."}}],"speaking":[{"id":"restaurant-order-speaking-1","prompt":{"en":"Say you want one bowl of beef noodles and no spice.","fr":"Dis que tu veux un bol de nouilles au bœuf sans piment."},"target":"我要一碗牛肉面，不要辣。","audio":"/audio/restaurant-order/practice-speaking-01.mp3","explanation":{"en":"This is the core safe ordering sentence.","fr":"C''est la phrase principale pour commander sans risque."}},{"id":"restaurant-order-speaking-2","prompt":{"en":"Ask if they have cola.","fr":"Demande s''ils ont du cola."},"target":"有可乐吗？","audio":"/audio/restaurant-order/practice-speaking-02.mp3","explanation":{"en":"A quick drink question after ordering food.","fr":"Une question rapide sur les boissons après avoir commandé."}}],"reading":[{"id":"restaurant-order-reading-1","prompt":{"en":"Match the total-price question on a small bill.","fr":"Associe la question du prix total sur une petite addition."},"target":"一共多少钱？","audio":"/audio/restaurant-order/practice-reading-01.mp3","explanation":{"en":"Use this when all items are ready and you need the total.","fr":"Utilise cela quand les articles sont prêts et que tu veux le total."}},{"id":"restaurant-order-reading-2","prompt":{"en":"Match the word for paying the bill.","fr":"Associe le mot pour payer l''addition."},"target":"买单","audio":"/audio/restaurant-order/practice-reading-02.mp3","explanation":{"en":"买单 is how you ask for the check.","fr":"买单 est la façon de demander l''addition."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
