(71, 'restaurant-order', 'reviewCards', '[{"id":"restaurant-order-review-1","front":"菜单","back":{"en":"menu","fr":"menu"},"explanation":{"en":"Ask 有菜单吗？ to see it.","fr":"Demande 有菜单吗？ pour le voir."}},{"id":"restaurant-order-review-2","front":"牛肉面","back":{"en":"beef noodles","fr":"nouilles au bœuf"},"explanation":{"en":"Order it with 我要一碗牛肉面。","fr":"Commande-le avec 我要一碗牛肉面。"}},{"id":"restaurant-order-review-3","front":"不要辣","back":{"en":"not spicy / no chili","fr":"sans piment"},"explanation":{"en":"A concise food safety preference.","fr":"Une préférence alimentaire concise."}},{"id":"restaurant-order-review-4","front":"大份 / 小份","back":{"en":"large / small portion","fr":"grande / petite portion"},"explanation":{"en":"Choose your portion size when ordering.","fr":"Choisis la taille de ta portion en commandant."}},{"id":"restaurant-order-review-5","front":"带走","back":{"en":"take away","fr":"à emporter"},"explanation":{"en":"Say this to take the food with you.","fr":"Dis ceci pour emporter la nourriture."}},{"id":"restaurant-order-review-6","front":"买单","back":{"en":"pay the bill","fr":"payer l''addition"},"explanation":{"en":"Ask the server for the check.","fr":"Demande l''addition au serveur."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
