(73, 'train-station-ticket', 'lessonMeta', '{"id":"train-station-ticket","title":{"en":"坐火车 / Take the train","fr":"坐火车 / Prendre le train"},"scenario":{"en":"Most train tickets are booked online, but these phrases help you navigate the station.","fr":"La plupart des billets de train se réservent en ligne, mais ces phrases t''aident à te repérer en gare."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(74, 'train-station-ticket', 'lessonMeta', '{"id":"train-station-ticket","title":{"en":"坐火车 / Take the train","fr":"坐火车 / Prendre le train"},"scenario":{"en":"Most train tickets are booked online, but these phrases help you navigate the station.","fr":"La plupart des billets de train se réservent en ligne, mais ces phrases t''aident à te repérer en gare."}}', 'draft', 73, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(75, 'train-station-ticket', 'dialogue', '{"title":{"en":"Buy a train ticket and find your platform","fr":"Acheter un billet de train et trouver son quai"},"lines":[{"id":"train-station-ticket-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，我想买一张去上海的票。","pinyin":"Nǐ hǎo, wǒ xiǎng mǎi yì zhāng qù Shànghǎi de piào.","translation":{"en":"Hello, I would like to buy one ticket to Shanghai.","fr":"Bonjour, je voudrais acheter un billet pour Shanghai."},"explanation":{"en":"This capstone ticket phrase extends the metro ticket pattern with 我想买.","fr":"Cette phrase de billet finale prolonge le modèle du ticket de métro avec 我想买."},"audio":"/audio/train-station-ticket/line-01.mp3"},{"id":"train-station-ticket-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"今天还是明天？","pinyin":"Jīntiān háishi míngtiān?","translation":{"en":"Today or tomorrow?","fr":"Aujourd''hui ou demain ?"},"explanation":{"en":"还是 presents two choices in a question.","fr":"还是 présente deux choix dans une question."},"audio":"/audio/train-station-ticket/line-02.mp3"},{"id":"train-station-ticket-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"今天下午，有票吗？","pinyin":"Jīntiān xiàwǔ, yǒu piào ma?","translation":{"en":"This afternoon, are there tickets?","fr":"Cet après-midi, y a-t-il des billets ?"},"explanation":{"en":"有票吗 confirms availability for your chosen time.","fr":"有票吗 confirme la disponibilité pour l''horaire choisi."},"audio":"/audio/train-station-ticket/line-03.mp3"},{"id":"train-station-ticket-line-04","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"有。硬座还是软座？","pinyin":"Yǒu. Yìngzuò háishi ruǎnzuò?","translation":{"en":"Yes. Hard seat or soft seat?","fr":"Oui. Place dure ou place molle ?"},"explanation":{"en":"硬座 is the basic seat; 软座 is more comfortable and costs more.","fr":"硬座 est la place de base ; 软座 est plus confortable et coûte plus cher."},"audio":"/audio/train-station-ticket/line-04.mp3"},{"id":"train-station-ticket-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"硬座。请出示护照吗？","pinyin":"Yìngzuò. Qǐng chūshì hùzhào ma?","translation":{"en":"Hard seat. Do I need to show my passport?","fr":"Place dure. Dois-je présenter mon passeport ?"},"explanation":{"en":"The traveler anticipates the passport requirement learned in earlier lessons.","fr":"Le voyageur anticipe la demande de passeport apprise dans les leçons précédentes."},"audio":"/audio/train-station-ticket/line-05.mp3"},{"id":"train-station-ticket-line-06","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"对，请出示护照。这是您的票。","pinyin":"Duì, qǐng chūshì hùzhào. Zhè shì nín de piào.","translation":{"en":"Yes, please show your passport. This is your ticket.","fr":"Oui, veuillez présenter votre passeport. Voici votre billet."},"explanation":{"en":"The clerk confirms the passport step and hands over the ticket.","fr":"L''employé confirme l''étape du passeport et remet le billet."},"audio":"/audio/train-station-ticket/line-06.mp3"},{"id":"train-station-ticket-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"在哪个站台？几点出发？","pinyin":"Zài nǎge zhàntái? Jǐ diǎn chūfā?","translation":{"en":"Which platform? What time does it depart?","fr":"Quel quai ? À quelle heure part-il ?"},"explanation":{"en":"站台 is the platform; 几点出发 asks for the exact departure time.","fr":"站台 est le quai ; 几点出发 demande l''heure exacte de départ."},"audio":"/audio/train-station-ticket/line-07.mp3"},{"id":"train-station-ticket-line-08","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"二号站台，三点出发。不会晚点。","pinyin":"Èr hào zhàntái, sān diǎn chūfā. Bú huì wǎndiǎn.","translation":{"en":"Platform two, departs at three o''clock. It won''t be delayed.","fr":"Quai numéro deux, départ à trois heures. Il n''y aura pas de retard."},"explanation":{"en":"不会晚点 reassures you that the train is on time.","fr":"不会晚点 te rassure que le train est à l''heure."},"audio":"/audio/train-station-ticket/line-08.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(76, 'train-station-ticket', 'dialogue', '{"title":{"en":"Buy a train ticket and find your platform","fr":"Acheter un billet de train et trouver son quai"},"lines":[{"id":"train-station-ticket-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，我想买一张去上海的票。","pinyin":"Nǐ hǎo, wǒ xiǎng mǎi yì zhāng qù Shànghǎi de piào.","translation":{"en":"Hello, I would like to buy one ticket to Shanghai.","fr":"Bonjour, je voudrais acheter un billet pour Shanghai."},"explanation":{"en":"This capstone ticket phrase extends the metro ticket pattern with 我想买.","fr":"Cette phrase de billet finale prolonge le modèle du ticket de métro avec 我想买."},"audio":"/audio/train-station-ticket/line-01.mp3"},{"id":"train-station-ticket-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"今天还是明天？","pinyin":"Jīntiān háishi míngtiān?","translation":{"en":"Today or tomorrow?","fr":"Aujourd''hui ou demain ?"},"explanation":{"en":"还是 presents two choices in a question.","fr":"还是 présente deux choix dans une question."},"audio":"/audio/train-station-ticket/line-02.mp3"},{"id":"train-station-ticket-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"今天下午，有票吗？","pinyin":"Jīntiān xiàwǔ, yǒu piào ma?","translation":{"en":"This afternoon, are there tickets?","fr":"Cet après-midi, y a-t-il des billets ?"},"explanation":{"en":"有票吗 confirms availability for your chosen time.","fr":"有票吗 confirme la disponibilité pour l''horaire choisi."},"audio":"/audio/train-station-ticket/line-03.mp3"},{"id":"train-station-ticket-line-04","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"有。硬座还是软座？","pinyin":"Yǒu. Yìngzuò háishi ruǎnzuò?","translation":{"en":"Yes. Hard seat or soft seat?","fr":"Oui. Place dure ou place molle ?"},"explanation":{"en":"硬座 is the basic seat; 软座 is more comfortable and costs more.","fr":"硬座 est la place de base ; 软座 est plus confortable et coûte plus cher."},"audio":"/audio/train-station-ticket/line-04.mp3"},{"id":"train-station-ticket-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"硬座。请出示护照吗？","pinyin":"Yìngzuò. Qǐng chūshì hùzhào ma?","translation":{"en":"Hard seat. Do I need to show my passport?","fr":"Place dure. Dois-je présenter mon passeport ?"},"explanation":{"en":"The traveler anticipates the passport requirement learned in earlier lessons.","fr":"Le voyageur anticipe la demande de passeport apprise dans les leçons précédentes."},"audio":"/audio/train-station-ticket/line-05.mp3"},{"id":"train-station-ticket-line-06","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"对，请出示护照。这是您的票。","pinyin":"Duì, qǐng chūshì hùzhào. Zhè shì nín de piào.","translation":{"en":"Yes, please show your passport. This is your ticket.","fr":"Oui, veuillez présenter votre passeport. Voici votre billet."},"explanation":{"en":"The clerk confirms the passport step and hands over the ticket.","fr":"L''employé confirme l''étape du passeport et remet le billet."},"audio":"/audio/train-station-ticket/line-06.mp3"},{"id":"train-station-ticket-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"在哪个站台？几点出发？","pinyin":"Zài nǎge zhàntái? Jǐ diǎn chūfā?","translation":{"en":"Which platform? What time does it depart?","fr":"Quel quai ? À quelle heure part-il ?"},"explanation":{"en":"站台 is the platform; 几点出发 asks for the exact departure time.","fr":"站台 est le quai ; 几点出发 demande l''heure exacte de départ."},"audio":"/audio/train-station-ticket/line-07.mp3"},{"id":"train-station-ticket-line-08","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"二号站台，三点出发。不会晚点。","pinyin":"Èr hào zhàntái, sān diǎn chūfā. Bú huì wǎndiǎn.","translation":{"en":"Platform two, departs at three o''clock. It won''t be delayed.","fr":"Quai numéro deux, départ à trois heures. Il n''y aura pas de retard."},"explanation":{"en":"不会晚点 reassures you that the train is on time.","fr":"不会晚点 te rassure que le train est à l''heure."},"audio":"/audio/train-station-ticket/line-08.mp3"}]}', 'draft', 75, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(77, 'train-station-ticket', 'sentencePatterns', '[{"id":"train-station-ticket-pattern-1","pattern":"……在哪里？","meaning":{"en":"Where is ...?","fr":"Où est ... ?"},"example":"火车站在哪里？","audio":"/audio/train-station-ticket/pattern-01.mp3","explanation":{"en":"Ask 在哪里 to find the station, ticket office, or dining car.","fr":"Demande 在哪里 pour trouver la gare, le guichet ou la voiture-restaurant."}},{"id":"train-station-ticket-pattern-2","pattern":"我要一张去……的票。","meaning":{"en":"I want to buy one ticket to ...","fr":"Je veux acheter un billet pour ..."},"example":"我要一张去北京的票。","audio":"/audio/train-station-ticket/pattern-02.mp3","explanation":{"en":"Swap in the city name for 北京 to name your destination.","fr":"Remplace 北京 par le nom de ta ville pour indiquer ta destination."}},{"id":"train-station-ticket-pattern-3","pattern":"……几点开？","meaning":{"en":"What time does ... leave?","fr":"À quelle heure part ... ?"},"example":"火车几点开？","audio":"/audio/train-station-ticket/pattern-03.mp3","explanation":{"en":"Ask 几点开 to check when the train departs.","fr":"Demande 几点开 pour vérifier l''heure de départ du train."}},{"id":"train-station-ticket-pattern-4","pattern":"……晚点了吗？","meaning":{"en":"Is ... delayed?","fr":"... est-il en retard ?"},"example":"火车晚点了吗？","audio":"/audio/train-station-ticket/pattern-04.mp3","explanation":{"en":"Ask 晚点了吗 to check if the train is running late.","fr":"Demande 晚点了吗 pour vérifier si le train est en retard."}},{"id":"train-station-ticket-pattern-5","pattern":"怎么换乘？","meaning":{"en":"How do I make a transit?","fr":"Comment faire une correspondance ?"},"example":"请问怎么换乘？","audio":"/audio/train-station-ticket/pattern-05.mp3","explanation":{"en":"Ask 怎么换乘 when you need to change trains.","fr":"Demande 怎么换乘 quand tu dois changer de train."}},{"id":"train-station-ticket-pattern-6","pattern":"售票处在哪里？","meaning":{"en":"Where is the ticket office?","fr":"Où est le guichet de billets ?"},"example":"售票处在哪里？","audio":"/audio/train-station-ticket/pattern-06.mp3","explanation":{"en":"Ask 售票处在哪里 to find the ticket office at the station.","fr":"Demande 售票处在哪里 pour trouver le guichet de billets en gare."}},{"id":"train-station-ticket-pattern-7","pattern":"这是我的护照。","meaning":{"en":"This is my passport.","fr":"Voici mon passeport."},"example":"这是我的护照。","audio":"/audio/train-station-ticket/pattern-07.mp3","explanation":{"en":"Hand over your passport with 这是我的护照 when buying a ticket.","fr":"Présente ton passeport avec 这是我的护照 quand tu achètes un billet."}},{"id":"train-station-ticket-pattern-8","pattern":"餐车在哪里？","meaning":{"en":"Where is the dining car?","fr":"Où est la voiture-restaurant ?"},"example":"餐车在哪里？","audio":"/audio/train-station-ticket/pattern-08.mp3","explanation":{"en":"Ask 餐车在哪里 to find the dining car on the train.","fr":"Demande 餐车在哪里 pour trouver la voiture-restaurant dans le train."}},{"id":"train-station-ticket-pattern-9","pattern":"我误车了。","meaning":{"en":"I missed my train.","fr":"J''ai raté mon train."},"example":"我误车了。","audio":"/audio/train-station-ticket/pattern-09.mp3","explanation":{"en":"Say 我误车了 to tell staff you missed your train.","fr":"Dis 我误车了 pour dire au personnel que tu as raté ton train."}},{"id":"train-station-ticket-pattern-10","pattern":"我没赶上火车。","meaning":{"en":"I missed the train.","fr":"J''ai raté le train."},"example":"我没赶上火车。","audio":"/audio/train-station-ticket/pattern-10.mp3","explanation":{"en":"Another way to say 我没赶上火车 when you arrived too late.","fr":"Une autre façon de dire que tu es arrivé trop tard pour le train."}},{"id":"train-station-ticket-pattern-11","pattern":"能改签下一辆车吗？","meaning":{"en":"Can I change my ticket for a later train?","fr":"Puis-je modifier mon billet pour un train suivant ?"},"example":"能改签下一辆车吗？","audio":"/audio/train-station-ticket/pattern-11.mp3","explanation":{"en":"Ask 能改签 to exchange your ticket for a later train.","fr":"Demande 能改签 pour échanger ton billet contre un train suivant."}},{"id":"train-station-ticket-pattern-12","pattern":"如何退票退款呢？","meaning":{"en":"How can I get a ticket cancellation and refund?","fr":"Comment obtenir l''annulation et le remboursement du billet ?"},"example":"如何退票退款呢？","audio":"/audio/train-station-ticket/pattern-12.mp3","explanation":{"en":"Ask 如何退票退款 to learn how to cancel and get a refund.","fr":"Demande 如何退票退款 pour savoir comment annuler et te faire rembourser."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
