anation":{"en":"站台 is the platform where you board. Look for it on signs.","fr":"站台 est le quai où tu embarques. Cherche-le sur les panneaux."}}]}', 'draft', 81, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(83, 'train-station-ticket', 'reviewCards', '[{"id":"train-station-ticket-review-1","front":"火车站","back":{"en":"train station","fr":"gare"},"explanation":{"en":"The setting for buying the ticket.","fr":"Le lieu où acheter le billet."}},{"id":"train-station-ticket-review-2","front":"车票","back":{"en":"ticket","fr":"billet"},"explanation":{"en":"A station ticket word.","fr":"Un mot de billet en gare."}},{"id":"train-station-ticket-review-3","front":"三点出发","back":{"en":"departs at three o''clock","fr":"départ à trois heures"},"explanation":{"en":"A compact phrase for the departure time.","fr":"Une phrase compacte pour l''heure de départ."}},{"id":"train-station-ticket-review-4","front":"硬座","back":{"en":"hard seat","fr":"place dure"},"explanation":{"en":"The standard train seat class in China.","fr":"La classe de place standard en train en Chine."}},{"id":"train-station-ticket-review-5","front":"站台","back":{"en":"platform","fr":"quai"},"explanation":{"en":"Find this word on signs to locate your boarding area.","fr":"Trouve ce mot sur les panneaux pour localiser ta zone d''embarquement."}},{"id":"train-station-ticket-review-6","front":"晚点","back":{"en":"delay","fr":"retard"},"explanation":{"en":"Watch for this word on departure boards.","fr":"Surveille ce mot sur les panneaux de départ."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(84, 'train-station-ticket', 'reviewCards', '[{"id":"train-station-ticket-review-1","front":"火车站","back":{"en":"train station","fr":"gare"},"explanation":{"en":"The setting for buying the ticket.","fr":"Le lieu où acheter le billet."}},{"id":"train-station-ticket-review-2","front":"车票","back":{"en":"ticket","fr":"billet"},"explanation":{"en":"A station ticket word.","fr":"Un mot de billet en gare."}},{"id":"train-station-ticket-review-3","front":"三点出发","back":{"en":"departs at three o''clock","fr":"départ à trois heures"},"explanation":{"en":"A compact phrase for the departure time.","fr":"Une phrase compacte pour l''heure de départ."}},{"id":"train-station-ticket-review-4","front":"硬座","back":{"en":"hard seat","fr":"place dure"},"explanation":{"en":"The standard train seat class in China.","fr":"La classe de place standard en train en Chine."}},{"id":"train-station-ticket-review-5","front":"站台","back":{"en":"platform","fr":"quai"},"explanation":{"en":"Find this word on signs to locate your boarding area.","fr":"Trouve ce mot sur les panneaux pour localiser ta zone d''embarquement."}},{"id":"train-station-ticket-review-6","front":"晚点","back":{"en":"delay","fr":"retard"},"explanation":{"en":"Watch for this word on departure boards.","fr":"Surveille ce mot sur les panneaux de départ."}}]', 'draft', 83, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(85, 'metro-ticket', 'lessonMeta', '{"id":"metro-ticket","title":{"en":"坐地铁 / Subway ride","fr":"坐地铁 / En métro"},"scenario":{"en":"Buy a ticket, make a transit, ask for help, go in the right direction and find the right exit.","fr":"Acheter un ticket, faire une correspondance, demander de l''aide, aller dans la bonne direction et trouver la bonne sortie."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(86, 'metro-ticket', 'lessonMeta', '{"id":"metro-ticket","title":{"en":"坐地铁 / Subway ride","fr":"坐地铁 / En métro"},"scenario":{"en":"Buy a ticket, make a transit, ask for help, go in the right direction and find the right exit.","fr":"Acheter un ticket, faire une correspondance, demander de l''aide, aller dans la bonne direction et trouver la bonne sortie."}}', 'draft', 85, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(87, 'metro-ticket', 'dialogue', '{"title":{"en":"Ask for a route and ticket","fr":"Demander un itinéraire et un ticket"},"lines":[{"id":"metro-ticket-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"去人民广场怎么走？","pinyin":"Qù Rénmín Guǎngchǎng zěnme zǒu?","translation":{"en":"How do I get to People''s Square?","fr":"Comment aller à la Place du Peuple ?"},"explanation":{"en":"去……怎么走 is the basic route question for a station or place.","fr":"去……怎么走 est la question de base pour demander un itinéraire vers une station ou un lieu."},"audio":"/audio/metro-ticket/line-01.mp3"},{"id":"metro-ticket-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"坐二号线。","pinyin":"Zuò èr hào xiàn.","translation":{"en":"Take line two.","fr":"Prenez la ligne 2."},"explanation":{"en":"号线 names the numbered metro line.","fr":"号线 indique la ligne de métro numérotée."},"audio":"/audio/metro-ticket/line-02.mp3"},{"id":"metro-ticket-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我要一张去人民广场的票。","pinyin":"Wǒ yào yì zhāng qù Rénmín Guǎngchǎng de piào.","translation":{"en":"I want one ticket to People''s Square.","fr":"Je voudrais un ticket pour la Place du Peuple."},"explanation":{"en":"一张 is the measure word for one ticket.","fr":"一张 est le classificateur pour un ticket."},"audio":"/audio/metro-ticket/line-03.mp3"},{"id":"metro-ticket-line-04","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"要几站？","pinyin":"Yào jǐ zhàn?","translation":{"en":"How many stops does it take?","fr":"Combien de stations faut-il ?"},"explanation":{"en":"要几站 is short and useful when you are counting stops.","fr":"要几站 est court et utile pour compter les stations."},"audio":"/audio/metro-ticket/line-04.mp3"},{"id":"metro-ticket-line-05","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"三站。","pinyin":"Sān zhàn.","translation":{"en":"Three stops.","fr":"Trois stations."},"explanation":{"en":"Listen for a number plus 站 when someone answers.","fr":"Écoute un nombre suivi de 站 quand quelqu''un répond."},"audio":"/audio/metro-ticket/line-05.mp3"},{"id":"metro-ticket-line-06","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"需要换乘吗？","pinyin":"Xūyào huànchéng ma?","translation":{"en":"Do I need to transfer?","fr":"Dois-je faire une correspondance ?"},"explanation":{"en":"Ask 需要换乘吗 to confirm if the route needs a transfer.","fr":"Demande 需要换乘吗 pour confirmer si le trajet nécessite une correspondance."},"audio":"/audio/metro-ticket/line-06.mp3"},{"id":"metro-ticket-line-07","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"不需要，一共三块钱。","pinyin":"Bù xūyào, yígòng sān kuài qián.","translation":{"en":"No transfer needed, three yuan in total.","fr":"Pas de correspondance, trois yuans au total."},"explanation":{"en":"The clerk confirms no transfer and gives the fare price.","fr":"L''employé confirme qu''il n''y a pas de correspondance et donne le prix."},"audio":"/audio/metro-ticket/line-07.mp3"},{"id":"metro-ticket-line-08","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"哪个出口出去？","pinyin":"Nǎge chūkǒu chūqù?","translation":{"en":"Which exit should I take?","fr":"Quelle sortie dois-je prendre ?"},"explanation":{"en":"Ask 哪个出口 when you arrive and need the right exit for your destination.","fr":"Demande 哪个出口 à l''arrivée pour trouver la bonne sortie vers ta destination."},"audio":"/audio/metro-ticket/line-08.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(88, 'metro-ticket', 'dialogue', '{"title":{"en":"Ask for a route and ticket","fr":"Demander un itinéraire et un ticket"},"lines":[{"id":"metro-ticket-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"去人民广场怎么走？","pinyin":"Qù Rénmín Guǎngchǎng zěnme zǒu?","translation":{"en":"How do I get to People''s Square?","fr":"Comment aller à la Place du Peuple ?"},"explanation":{"en":"去……怎么走 is the basic route question for a station or place.","fr":"去……怎么走 est la question de base pour demander un itinéraire vers une station ou un lieu."},"audio":"/audio/metro-ticket/line-01.mp3"},{"id":"metro-ticket-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"坐二号线。","pinyin":"Zuò èr hào xiàn.","translation":{"en":"Take line two.","fr":"Prenez la ligne 2."},"explanation":{"en":"号线 names the numbered metro line.","fr":"号线 indique la ligne de métro numérotée."},"audio":"/audio/metro-ticket/line-02.mp3"},{"id":"metro-ticket-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我要一张去人民广场的票。","pinyin":"Wǒ yào yì zhāng qù Rénmín Guǎngchǎng de piào.","translation":{"en":"I want one ticket to People''s Square.","fr":"Je voudrais un ticket pour la Place du Peuple."},"explanation":{"en":"一张 is the measure word for one ticket.","fr":"一张 est le classificateur pour un ticket."},"audio":"/audio/metro-ticket/line-03.mp3"},{"id":"metro-ticket-line-04","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"要几站？","pinyin":"Yào jǐ zhàn?","translation":{"en":"How many stops does it take?","fr":"Combien de stations faut-il ?"},"explanation":{"en":"要几站 is short and useful when you are counting stops.","fr":"要几站 est court et utile pour compter les stations."},"audio":"/audio/metro-ticket/line-04.mp3"},{"id":"metro-ticket-line-05","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"三站。","pinyin":"Sān zhàn.","translation":{"en":"Three stops.","fr":"Trois stations."},"explanation":{"en":"Listen for a number plus 站 when someone answers.","fr":"Écoute un nombre suivi de 站 quand quelqu''un répond."},"audio":"/audio/metro-ticket/line-05.mp3"},{"id":"metro-ticket-line-06","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"需要换乘吗？","pinyin":"Xūyào huànchéng ma?","translation":{"en":"Do I need to transfer?","fr":"Dois-je faire une correspondance ?"},"explanation":{"en":"Ask 需要换乘吗 to confirm if the route needs a transfer.","fr":"Demande 需要换乘吗 pour confirmer si le trajet nécessite une correspondance."},"audio":"/audio/metro-ticket/line-06.mp3"},{"id":"metro-ticket-line-07","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"不需要，一共三块钱。","pinyin":"Bù xūyào, yígòng sān kuài qián.","translation":{"en":"No transfer needed, three yuan in total.","fr":"Pas de correspondance, trois yuans au total."},"explanation":{"en":"The clerk confirms no transfer and gives the fare price.","fr":"L''employé confirme qu''il n''y a pas de correspondance et donne le prix."},"audio":"/audio/metro-ticket/line-07.mp3"},{"id":"metro-ticket-line-08","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"哪个出口出去？","pinyin":"Nǎge chūkǒu chūqù?","translation":{"en":"Which exit should I take?","fr":"Quelle sortie dois-je prendre ?"},"explanation":{"en":"Ask 哪个出口 when you arrive and need the right exit for your destination.","fr":"Demande 哪个出口 à l''arrivée pour trouver la bonne sortie vers ta destination."},"audio":"/audio/metro-ticket/line-08.mp3"}]}', 'draft', 87, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(89, 'metro-ticket', 'sentencePatterns', '[{"id":"metro-ticket-pattern-1","pattern":"……在哪里？","meaning":{"en":"Excuse me, where is ...?","fr":"Où est ... ?"},"example":"请问地铁站在哪里？","audio":"/audio/metro-ticket/pattern-01.mp3","explanation":{"en":"Ask 在哪里 to find the metro station or a place.","fr":"Demande 在哪里 pour trouver la station de métro ou un lieu."}},{"id":"metro-ticket-pattern-2","pattern":"我要去……。","meaning":{"en":"I want to go to ...","fr":"Je veux aller à ..."},"example":"我要去天安门广场。","audio":"/audio/metro-ticket/pattern-02.mp3","explanation":{"en":"Name your destination with 我要去 to tell the ticket seller.","fr":"Nomme ta destination avec 我要去 pour la dire au vendeur de tickets."}},{"id":"metro-ticket-pattern-3","pattern":"……怎么用？","meaning":{"en":"Could you show me how to use ...?","fr":"Comment utiliser ... ?"},"example":"自动售票机怎么用？","audio":"/audio/metro-ticket/pattern-03.mp3","explanation":{"en":"Ask 怎么用 when you need help using a machine.","fr":"Demande 怎么用 quand tu as besoin d''aide pour utiliser une machine."}},{"id":"metro-ticket-pattern-4","pattern":"在哪儿换乘？","meaning":{"en":"Where do I make a transfer?","fr":"Où fait-on la correspondance ?"},"example":"请问在哪儿换乘？","audio":"/audio/metro-ticket/pattern-04.mp3","explanation":{"en":"Ask 在哪儿换乘 to find the transfer point.","fr":"Demande 在哪儿换乘 pour trouver le point de correspondance."}},{"id":"metro-ticket-pattern-5","pattern":"是这个方向吗？","meaning":{"en":"Is this the right direction?","fr":"Est-ce la bonne direction ?"},"example":"是这个方向吗？","audio":"/audio/metro-ticket/pattern-05.mp3","explanation":{"en":"Confirm you are going the right way with 是这个方向吗.","fr":"Confirme que tu vas dans le bon sens avec 是这个方向吗."}},{"id":"metro-ticket-pattern-6","pattern":"在哪儿买票？","meaning":{"en":"Where can I buy a ticket?","fr":"Où puis-je acheter un ticket ?"},"example":"在哪儿买票？","audio":"/audio/metro-ticket/pattern-06.mp3","explanation":{"en":"Ask 在哪儿买票 to find where to buy a metro ticket.","fr":"Demande 在哪儿买票 pour trouver où acheter un ticket de métro."}},{"id":"metro-ticket-pattern-7","pattern":"您好，我要一张票。","meaning":{"en":"Hello, I want to buy a ticket.","fr":"Bonjour, je voudrais un ticket."},"example":"您好，我要一张票。","audio":"/audio/metro-ticket/pattern-07.mp3","explanation":{"en":"Ask 我要一张票 to buy a single metro ticket.","fr":"Demande 我要一张票 pour acheter un ticket de métro."}},{"id":"metro-ticket-pattern-8","pattern":"我要去这里。","meaning":{"en":"I want to go to this place.","fr":"Je veux aller à cet endroit."},"example":"我要去这里。","audio":"/audio/metro-ticket/pattern-08.mp3","explanation":{"en":"Point at a map and say 我要去这里 to show your destination.","fr":"Montre une carte et dis 我要去这里 pour indiquer ta destination."}},{"id":"metro-ticket-pattern-9","pattern":"请问，哪个出口去？","meaning":{"en":"Excuse me, which exit should I take?","fr":"Excusez-moi, quelle sortie dois-je prendre ?"},"example":"请问，哪个出口去？","audio":"/audio/metro-ticket/pattern-09.mp3","explanation":{"en":"Ask 哪个出口去 to find the right exit for your destination.","fr":"Demande 哪个出口去 pour trouver la bonne sortie vers ta destination."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(90, 'metro-ticket', 'sentencePatterns', '[{"id":"metro-ticket-pattern-1","pattern":"……在哪里？","meaning":{"en":"Excuse me, where is ...?","fr":"Où est ... ?"},"example":"请问地铁站在哪里？","audio":"/audio/metro-ticket/pattern-01.mp3","explanation":{"en":"Ask 在哪里 to find the metro station or a place.","fr":"Demande 在哪里 pour trouver la station de métro ou un lieu."}},{"id":"metro-ticket-pattern-2","pattern":"我要去……。","meaning":{"en":"I want to go to ...","fr":"Je veux aller à ..."},"example":"我要去天安门广场。","audio":"/audio/metro-ticket/pattern-02.mp3","explanation":{"en":"Name your destination with 我要去 to tell the ticket seller.","fr":"Nomme ta destination avec 我要去 pour la dire au vendeur de tickets."}},{"id":"metro-ticket-pattern-3","pattern":"……怎么用？","meaning":{"en":"Could you show me how to use ...?","fr":"Comment utiliser ... ?"},"example":"自动售票机怎么用？","audio":"/audio/metro-ticket/pattern-03.mp3","explanation":{"en":"Ask 怎么用 when you need help using a machine.","fr":"Demande 怎么用 quand tu as besoin d''aide pour utiliser une machine."}},{"id":"metro-ticket-pattern-4","pattern":"在哪儿换乘？","meaning":{"en":"Where do I make a transfer?","fr":"Où fait-on la correspondance ?"},"example":"请问在哪儿换乘？","audio":"/audio/metro-ticket/pattern-04.mp3","explanation":{"en":"Ask 在哪儿换乘 to find the transfer point.","fr":"Demande 在哪儿换乘 pour trouver le point de correspondance."}},{"id":"metro-ticket-pattern-5","pattern":"是这个方向吗？","meaning":{"en":"Is this the right direction?","fr":"Est-ce la bonne direction ?"},"example":"是这个方向吗？","audio":"/audio/metro-ticket/pattern-05.mp3","explanation":{"en":"Confirm you are going the right way with 是这个方向吗.","fr":"Confirme que tu vas dans le bon sens avec 是这个方向吗."}},{"id":"metro-ticket-pattern-6","pattern":"在哪儿买票？","meaning":{"en":"Where can I buy a ticket?","fr":"Où puis-je acheter un ticket ?"},"example":"在哪儿买票？","audio":"/audio/metro-ticket/pattern-06.mp3","explanation":{"en":"Ask 在哪儿买票 to find where to buy a metro ticket.","fr":"Demande 在哪儿买票 pour trouver où acheter un ticket de métro."}},{"id":"metro-ticket-pattern-7","pattern":"您好，我要一张票。","meaning":{"en":"Hello, I want to buy a ticket.","fr":"Bonjour, je voudrais un ticket."},"example":"您好，我要一张票。","audio":"/audio/metro-ticket/pattern-07.mp3","explanation":{"en":"Ask 我要一张票 to buy a single metro ticket.","fr":"Demande 我要一张票 pour acheter un ticket de métro."}},{"id":"metro-ticket-pattern-8","pattern":"我要去这里。","meaning":{"en":"I want to go to this place.","fr":"Je veux aller à cet endroit."},"example":"我要去这里。","audio":"/audio/metro-ticket/pattern-08.mp3","explanation":{"en":"Point at a map and say 我要去这里 to show your destination.","fr":"Montre une carte et dis 我要去这里 pour indiquer ta destination."}},{"id":"metro-ticket-pattern-9","pattern":"请问，哪个出口去？","meaning":{"en":"Excuse me, which exit should I take?","fr":"Excusez-moi, quelle sortie dois-je prendre ?"},"example":"请问，哪个出口去？","audio":"/audio/metro-ticket/pattern-09.mp3","explanation":{"en":"Ask 哪个出口去 to find the right exit for your destination.","fr":"Demande 哪个出口去 pour trouver la bonne sortie vers ta destination."}}]', 'draft', 89, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(91, 'metro-ticket', 'vocabulary', '[{"id":"metro-ticket-vocab-1","hanzi":"地铁","pinyin":"dìtiě","audio":"/audio/metro-ticket/vocab-01.mp3","meaning":{"en":"metro / subway","fr":"métro"},"explanation":{"en":"The transportation system for this lesson.","fr":"Le moyen de transport de cette leçon."}},{"id":"metro-ticket-vocab-2","hanzi":"票","pinyin":"piào","audio":"/audio/metro-ticket/vocab-02.mp3","meaning":{"en":"ticket","fr":"ticket / billet"},"explanation":{"en":"A shared word for metro and train tickets.","fr":"Un mot commun pour les tickets de métro et billets de train."}},{"id":"metro-ticket-vocab-3","hanzi":"站","pinyin":"zhàn","audio":"/audio/metro-ticket/vocab-03.mp3","meaning":{"en":"stop / station","fr":"station / arrêt"},"explanation":{"en":"Count stops with a number plus 站.","fr":"Compte les stations avec un nombre suivi de 站."}},{"id":"metro-ticket-vocab-4","hanzi":"二号线","pinyin":"èr hào xiàn","audio":"/audio/metro-ticket/vocab-04.mp3","meaning":{"en":"Line 2","fr":"ligne 2"},"explanation":{"en":"A model phrase for numbered metro lines.","fr":"Une phrase modèle pour les lignes de métro numérotées."}},{"id":"metro-ticket-vocab-5","hanzi":"换乘","pinyin":"huànchéng","audio":"/audio/metro-ticket/vocab-05.mp3","meaning":{"en":"transfer","fr":"correspondance"},"explanation":{"en":"Recognize it on signs even if this first route stays simple.","fr":"Reconnais-le sur les panneaux même si ce premier trajet reste simple."}},{"id":"metro-ticket-vocab-6","hanzi":"出口","pinyin":"chūkǒu","audio":"/audio/metro-ticket/vocab-06.mp3","meaning":{"en":"exit","fr":"sortie"},"explanation":{"en":"Look for 出口 signs to leave the station.","fr":"Cherche les panneaux 出口 pour sortir de la station."}},{"id":"metro-ticket-vocab-7","hanzi":"公交卡","pinyin":"gōngjiāokǎ","audio":"/audio/metro-ticket/vocab-07.mp3","meaning":{"en":"transit card","fr":"carte de transport"},"explanation":{"en":"A rechargeable card for bus and metro rides.","fr":"Une carte rechargeable pour les trajets en bus et métro."}},{"id":"metro-ticket-vocab-8","hanzi":"一张","pinyin":"yì zhāng","audio":"/audio/metro-ticket/vocab-08.mp3","meaning":{"en":"one (for flat items like tickets)","fr":"un (pour les objets plats comme les tickets)"},"explanation":{"en":"Use 张 for tickets, paper, and flat objects.","fr":"Utilise 张 pour les tickets, le papier et les objets plats."}},{"id":"metro-ticket-vocab-9","hanzi":"充值","pinyin":"chōngzhí","audio":"/audio/metro-ticket/vocab-09.mp3","meaning":{"en":"top up / recharge","fr":"recharger"},"explanation":{"en":"Use 充值 to add money to your transit card.","fr":"Utilise 充值 pour ajouter de l''argent à ta carte de transport."}},{"id":"metro-ticket-vocab-10","hanzi":"方向","pinyin":"fāngxiàng","audio":"/audio/metro-ticket/vocab-10.mp3","meaning":{"en":"direction","fr":"direction"},"explanation":{"en":"Check 方向 on metro signs to know which platform to take.","fr":"Vérifie 方向 sur les panneaux de métro pour savoir quel quai prendre."}},{"id":"metro-ticket-vocab-11","hanzi":"入口","pinyin":"rùkǒu","audio":"/audio/metro-ticket/vocab-11.mp3","meaning":{"en":"entrance","fr":"entrée"},"explanation":{"en":"The entrance you use to go into the metro station.","fr":"L''entrée que tu utilises pour entrer dans la station de métro."}},{"id":"metro-ticket-vocab-12","hanzi":"自动售票机","pinyin":"zìdòng shòupiàojī","audio":"/audio/metro-ticket/vocab-12.mp3","meaning":{"en":"ticket vending machine","fr":"distributeur de tickets"},"explanation":{"en":"A machine where you buy your metro ticket.","fr":"Une machine où tu achètes ton ticket de métro."}},{"id":"metro-ticket-vocab-13","hanzi":"上车","pinyin":"shàng chē","audio":"/audio/metro-ticket/vocab-13.mp3","meaning":{"en":"get on the train","fr":"monter dans le train"},"explanation":{"en":"The action of boarding the train or metro.","fr":"L''action de monter dans le train ou le métro."}},{"id":"metro-ticket-vocab-14","hanzi":"下车","pinyin":"xià chē","audio":"/audio/metro-ticket/vocab-14.mp3","meaning":{"en":"get off the train","fr":"descendre du train"},"explanation":{"en":"The action of getting off at your stop.","fr":"L''action de descendre à ton arrêt."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
