(97, 'convenience-store-run', 'lessonMeta', '{"id":"convenience-store-run","title":{"en":"购物 / Shopping","fr":"购物 / Shopping"},"scenario":{"en":"Phrases to navigate stores, check prices, bargain and pay smoothly.","fr":"Des phrases pour se repérer en magasin, vérifier les prix, négocier et payer facilement."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(98, 'convenience-store-run', 'lessonMeta', '{"id":"convenience-store-run","title":{"en":"购物 / Shopping","fr":"购物 / Shopping"},"scenario":{"en":"Phrases to navigate stores, check prices, bargain and pay smoothly.","fr":"Des phrases pour se repérer en magasin, vérifier les prix, négocier et payer facilement."}}', 'draft', 97, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(99, 'convenience-store-run', 'dialogue', '{"title":{"en":"Buy one simple item","fr":"Acheter un article simple"},"lines":[{"id":"convenience-store-run-line-01","speaker":{"en":"Customer","fr":"Client"},"hanzi":"你好，我要一瓶水和一包薯片。","pinyin":"Nǐ hǎo, wǒ yào yì píng shuǐ hé yì bāo shǔpiàn.","translation":{"en":"Hello, I want a bottle of water and a bag of chips.","fr":"Bonjour, je voudrais une bouteille d''eau et un paquet de chips."},"explanation":{"en":"我要...和... combines two items with 和 in one short sentence.","fr":"我要...和... combine deux articles avec 和 dans une phrase courte."},"audio":"/audio/convenience-store-run/line-01.mp3"},{"id":"convenience-store-run-line-02","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"好的，还要别的吗？","pinyin":"Hǎo de, hái yào bié de ma?","translation":{"en":"Okay, do you want anything else?","fr":"D''accord, vous voulez autre chose ?"},"explanation":{"en":"还要别的吗 is a common checkout question after you name one item.","fr":"还要别的吗 est une question courante à la caisse après avoir nommé un article."},"audio":"/audio/convenience-store-run/line-02.mp3"},{"id":"convenience-store-run-line-03","speaker":{"en":"Customer","fr":"Client"},"hanzi":"不要了，一共多少钱？","pinyin":"Bú yào le, yígòng duōshao qián?","translation":{"en":"No more, how much is it altogether?","fr":"Rien d''autre, ça fait combien au total ?"},"explanation":{"en":"不要了 closes the shopping list, and 一共多少钱 asks the total price.","fr":"不要了 ferme la liste d''achats, et 一共多少钱 demande le prix total."},"audio":"/audio/convenience-store-run/line-03.mp3"},{"id":"convenience-store-run-line-04","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"九块钱。","pinyin":"Jiǔ kuài qián.","translation":{"en":"Nine yuan.","fr":"Neuf yuans."},"explanation":{"en":"块 is the everyday word you will hear for yuan in small purchases.","fr":"块 est le mot courant que tu entendras pour yuan dans les petits achats."},"audio":"/audio/convenience-store-run/line-04.mp3"},{"id":"convenience-store-run-line-05","speaker":{"en":"Customer","fr":"Client"},"hanzi":"可以用手机支付吗？","pinyin":"Kěyǐ yòng shǒujī zhīfù ma?","translation":{"en":"Can I pay by phone?","fr":"Puis-je payer avec mon téléphone ?"},"explanation":{"en":"This reuses the phone payment question from the previous lesson in a store.","fr":"Cette phrase réutilise la question de paiement mobile de la leçon précédente dans un magasin."},"audio":"/audio/convenience-store-run/line-05.mp3"},{"id":"convenience-store-run-line-06","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"可以，扫码这里。","pinyin":"Kěyǐ, sǎomǎ zhèlǐ.","translation":{"en":"Yes, scan here.","fr":"Oui, scannez ici."},"explanation":{"en":"扫码这里 points to the QR code on the counter or screen.","fr":"扫码这里 indique le code QR sur le comptoir ou l''écran."},"audio":"/audio/convenience-store-run/line-06.mp3"},{"id":"convenience-store-run-line-07","speaker":{"en":"Customer","fr":"Client"},"hanzi":"有袋子吗？","pinyin":"Yǒu dàizi ma?","translation":{"en":"Do you have a bag?","fr":"Avez-vous un sac ?"},"explanation":{"en":"Ask 有袋子吗？ if you need a plastic bag for your items.","fr":"Demande 有袋子吗？ si tu as besoin d''un sac plastique pour tes articles."},"audio":"/audio/convenience-store-run/line-07.mp3"},{"id":"convenience-store-run-line-08","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"有，两毛钱。","pinyin":"Yǒu, liǎng máo qián.","translation":{"en":"Yes, twenty cents.","fr":"Oui, vingt centimes."},"explanation":{"en":"Bags in some Chinese stores cost a small extra fee.","fr":"Les sacs dans certains magasins chinois coûtent un petit supplément."},"audio":"/audio/convenience-store-run/line-08.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
