omer","fr":"Client"},"hanzi":"可以用手机支付吗？","pinyin":"Kěyǐ yòng shǒujī zhīfù ma?","translation":{"en":"Can I pay by phone?","fr":"Puis-je payer avec mon téléphone ?"},"explanation":{"en":"This reuses the phone payment question from the previous lesson in a store.","fr":"Cette phrase réutilise la question de paiement mobile de la leçon précédente dans un magasin."},"audio":"/audio/convenience-store-run/line-05.mp3"},{"id":"convenience-store-run-line-06","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"可以，扫码这里。","pinyin":"Kěyǐ, sǎomǎ zhèlǐ.","translation":{"en":"Yes, scan here.","fr":"Oui, scannez ici."},"explanation":{"en":"扫码这里 points to the QR code on the counter or screen.","fr":"扫码这里 indique le code QR sur le comptoir ou l''écran."},"audio":"/audio/convenience-store-run/line-06.mp3"},{"id":"convenience-store-run-line-07","speaker":{"en":"Customer","fr":"Client"},"hanzi":"有袋子吗？","pinyin":"Yǒu dàizi ma?","translation":{"en":"Do you have a bag?","fr":"Avez-vous un sac ?"},"explanation":{"en":"Ask 有袋子吗？ if you need a plastic bag for your items.","fr":"Demande 有袋子吗？ si tu as besoin d''un sac plastique pour tes articles."},"audio":"/audio/convenience-store-run/line-07.mp3"},{"id":"convenience-store-run-line-08","speaker":{"en":"Clerk","fr":"Employé"},"hanzi":"有，两毛钱。","pinyin":"Yǒu, liǎng máo qián.","translation":{"en":"Yes, twenty cents.","fr":"Oui, vingt centimes."},"explanation":{"en":"Bags in some Chinese stores cost a small extra fee.","fr":"Les sacs dans certains magasins chinois coûtent un petit supplément."},"audio":"/audio/convenience-store-run/line-08.mp3"}]}', 'draft', 99, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(101, 'convenience-store-run', 'sentencePatterns', '[{"id":"convenience-store-run-pattern-1","pattern":"……多少钱?","meaning":{"en":"How much is this?","fr":"C''est combien ?"},"example":"这个多少钱?","audio":"/audio/convenience-store-run/pattern-01.mp3","explanation":{"en":"Point at an item and ask 这个多少钱 to check the price.","fr":"Montre un article et demande 这个多少钱 pour vérifier le prix."}},{"id":"convenience-store-run-pattern-2","pattern":"太……了。","meaning":{"en":"It''s too ...","fr":"C''est trop ..."},"example":"太贵了。","audio":"/audio/convenience-store-run/pattern-02.mp3","explanation":{"en":"太贵了 tells the seller the price feels too high.","fr":"太贵了 dit au vendeur que le prix est trop élevé."}},{"id":"convenience-store-run-pattern-3","pattern":"可以……吗?","meaning":{"en":"Can you ...?","fr":"Pouvez-vous ... ?"},"example":"可以便宜一点吗?","audio":"/audio/convenience-store-run/pattern-03.mp3","explanation":{"en":"Use 可以…吗 to ask politely for a lower price or other help.","fr":"Utilise 可以…吗 pour demander poliment un prix plus bas ou de l''aide."}},{"id":"convenience-store-run-pattern-4","pattern":"我买这个。","meaning":{"en":"I will buy this.","fr":"Je prends ceci."},"example":"我买这个。","audio":"/audio/convenience-store-run/pattern-04.mp3","explanation":{"en":"Say 我买这个 to confirm the item you want.","fr":"Dis 我买这个 pour confirmer l''article que tu veux."}},{"id":"convenience-store-run-pattern-5","pattern":"有……吗?","meaning":{"en":"Do you have ...?","fr":"Avez-vous ... ?"},"example":"有袋子吗?","audio":"/audio/convenience-store-run/pattern-05.mp3","explanation":{"en":"Use 有…吗 to check if an item or service is available.","fr":"Utilise 有…吗 pour vérifier si un article ou un service est disponible."}},{"id":"convenience-store-run-pattern-6","pattern":"我只是看看。","meaning":{"en":"I am just looking.","fr":"Je regarde juste."},"example":"我只是看看。","audio":"/audio/convenience-store-run/pattern-06.mp3","explanation":{"en":"Say 我只是看看 when you do not want to buy yet.","fr":"Dis 我只是看看 quand tu ne veux pas encore acheter."}},{"id":"convenience-store-run-pattern-7","pattern":"有别的颜色吗?","meaning":{"en":"Do you have other colors?","fr":"Avez-vous d''autres couleurs ?"},"example":"有别的颜色吗?","audio":"/audio/convenience-store-run/pattern-07.mp3","explanation":{"en":"Ask 有别的颜色吗 to check for other color options.","fr":"Demande 有别的颜色吗 pour vérifier les autres couleurs."}},{"id":"convenience-store-run-pattern-8","pattern":"我可以试试吗？","meaning":{"en":"Can I try it on?","fr":"Puis-je l''essayer ?"},"example":"我可以试试吗？","audio":"/audio/convenience-store-run/pattern-08.mp3","explanation":{"en":"Ask 我可以试试吗 before trying on clothing.","fr":"Demande 我可以试试吗 avant d''essayer des vêtements."}},{"id":"convenience-store-run-pattern-9","pattern":"试衣间在哪里?","meaning":{"en":"Where is the fitting room?","fr":"Où est la cabine d''essayage ?"},"example":"试衣间在哪里?","audio":"/audio/convenience-store-run/pattern-09.mp3","explanation":{"en":"Ask 试衣间在哪里 to find the fitting room.","fr":"Demande 试衣间在哪里 pour trouver la cabine d''essayage."}},{"id":"convenience-store-run-pattern-10","pattern":"有大号/小号吗?","meaning":{"en":"Do you have a large/small size?","fr":"Avez-vous une grande/petite taille ?"},"example":"有大号/小号吗?","audio":"/audio/convenience-store-run/pattern-10.mp3","explanation":{"en":"Ask 有大号/小号吗 to check available sizes.","fr":"Demande 有大号/小号吗 pour vérifier les tailles disponibles."}},{"id":"convenience-store-run-pattern-11","pattern":"可以刷卡吗?","meaning":{"en":"Can I pay by card?","fr":"Puis-je payer par carte ?"},"example":"可以刷卡吗?","audio":"/audio/convenience-store-run/pattern-11.mp3","explanation":{"en":"Ask 可以刷卡吗 to check if card payment is accepted.","fr":"Demande 可以刷卡吗 pour vérifier si le paiement par carte est accepté."}},{"id":"convenience-store-run-pattern-12","pattern":"我用微信支付 / 支付宝。","meaning":{"en":"I will use WeChat Pay / Alipay.","fr":"Je vais payer avec WeChat / Alipay."},"example":"我用微信支付 / 支付宝。","audio":"/audio/convenience-store-run/pattern-12.mp3","explanation":{"en":"Tell the clerk how you will pay with 微信支付 or 支付宝.","fr":"Indique au vendeur comment tu vas payer avec 微信支付 ou 支付宝."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
