heter."}},{"id":"convenience-store-run-pattern-7","pattern":"有别的颜色吗?","meaning":{"en":"Do you have other colors?","fr":"Avez-vous d''autres couleurs ?"},"example":"有别的颜色吗?","audio":"/audio/convenience-store-run/pattern-07.mp3","explanation":{"en":"Ask 有别的颜色吗 to check for other color options.","fr":"Demande 有别的颜色吗 pour vérifier les autres couleurs."}},{"id":"convenience-store-run-pattern-8","pattern":"我可以试试吗？","meaning":{"en":"Can I try it on?","fr":"Puis-je l''essayer ?"},"example":"我可以试试吗？","audio":"/audio/convenience-store-run/pattern-08.mp3","explanation":{"en":"Ask 我可以试试吗 before trying on clothing.","fr":"Demande 我可以试试吗 avant d''essayer des vêtements."}},{"id":"convenience-store-run-pattern-9","pattern":"试衣间在哪里?","meaning":{"en":"Where is the fitting room?","fr":"Où est la cabine d''essayage ?"},"example":"试衣间在哪里?","audio":"/audio/convenience-store-run/pattern-09.mp3","explanation":{"en":"Ask 试衣间在哪里 to find the fitting room.","fr":"Demande 试衣间在哪里 pour trouver la cabine d''essayage."}},{"id":"convenience-store-run-pattern-10","pattern":"有大号/小号吗?","meaning":{"en":"Do you have a large/small size?","fr":"Avez-vous une grande/petite taille ?"},"example":"有大号/小号吗?","audio":"/audio/convenience-store-run/pattern-10.mp3","explanation":{"en":"Ask 有大号/小号吗 to check available sizes.","fr":"Demande 有大号/小号吗 pour vérifier les tailles disponibles."}},{"id":"convenience-store-run-pattern-11","pattern":"可以刷卡吗?","meaning":{"en":"Can I pay by card?","fr":"Puis-je payer par carte ?"},"example":"可以刷卡吗?","audio":"/audio/convenience-store-run/pattern-11.mp3","explanation":{"en":"Ask 可以刷卡吗 to check if card payment is accepted.","fr":"Demande 可以刷卡吗 pour vérifier si le paiement par carte est accepté."}},{"id":"convenience-store-run-pattern-12","pattern":"我用微信支付 / 支付宝。","meaning":{"en":"I will use WeChat Pay / Alipay.","fr":"Je vais payer avec WeChat / Alipay."},"example":"我用微信支付 / 支付宝。","audio":"/audio/convenience-store-run/pattern-12.mp3","explanation":{"en":"Tell the clerk how you will pay with 微信支付 or 支付宝.","fr":"Indique au vendeur comment tu vas payer avec 微信支付 ou 支付宝."}}]', 'draft', 101, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(103, 'convenience-store-run', 'vocabulary', '[{"id":"convenience-store-run-vocab-1","hanzi":"一瓶水","pinyin":"yì píng shuǐ","audio":"/audio/convenience-store-run/vocab-01.mp3","meaning":{"en":"a bottle of water","fr":"une bouteille d''eau"},"explanation":{"en":"A useful first purchase item after arriving.","fr":"Un premier achat utile après l''arrivée."}},{"id":"convenience-store-run-vocab-2","hanzi":"还要别的吗","pinyin":"hái yào bié de ma","audio":"/audio/convenience-store-run/vocab-02.mp3","meaning":{"en":"anything else?","fr":"autre chose ?"},"explanation":{"en":"Listen for this checkout question after naming your item.","fr":"Écoute cette question à la caisse après avoir nommé ton article."}},{"id":"convenience-store-run-vocab-3","hanzi":"不要了","pinyin":"bú yào le","audio":"/audio/convenience-store-run/vocab-03.mp3","meaning":{"en":"no more / nothing else","fr":"rien d''autre"},"explanation":{"en":"Use it to say you do not need anything else.","fr":"Utilise-le pour dire que tu n''as besoin de rien d''autre."}},{"id":"convenience-store-run-vocab-4","hanzi":"一共","pinyin":"yígòng","audio":"/audio/convenience-store-run/vocab-04.mp3","meaning":{"en":"altogether / in total","fr":"au total"},"explanation":{"en":"This word prepares the total price question.","fr":"Ce mot prépare la question du prix total."}},{"id":"convenience-store-run-vocab-5","hanzi":"多少钱","pinyin":"duōshao qián","audio":"/audio/convenience-store-run/vocab-05.mp3","meaning":{"en":"how much money?","fr":"combien d''argent ? / combien ça coûte ?"},"explanation":{"en":"The key phrase for asking a simple price.","fr":"La phrase clé pour demander un prix simple."}},{"id":"convenience-store-run-vocab-6","hanzi":"薯片","pinyin":"shǔpiàn","audio":"/audio/convenience-store-run/vocab-06.mp3","meaning":{"en":"potato chips","fr":"chips"},"explanation":{"en":"A common snack to buy in convenience stores.","fr":"Un snack courant à acheter en supérette."}},{"id":"convenience-store-run-vocab-7","hanzi":"袋子","pinyin":"dàizi","audio":"/audio/convenience-store-run/vocab-07.mp3","meaning":{"en":"bag","fr":"sac"},"explanation":{"en":"Ask for a 袋子 if you need something to carry your items.","fr":"Demande un 袋子 si tu as besoin de porter tes articles."}},{"id":"convenience-store-run-vocab-8","hanzi":"扫码","pinyin":"sǎomǎ","audio":"/audio/convenience-store-run/vocab-08.mp3","meaning":{"en":"scan code / scan to pay","fr":"scanner le code / scanner pour payer"},"explanation":{"en":"The clerk points to the QR code and says this.","fr":"L''employé montre le code QR et dit ceci."}},{"id":"convenience-store-run-vocab-9","hanzi":"毛","pinyin":"máo","audio":"/audio/convenience-store-run/vocab-09.mp3","meaning":{"en":"dime / one-tenth of a yuan","fr":"dixième de yuan"},"explanation":{"en":"毛 is the smaller unit when a price is under one yuan.","fr":"毛 est la petite unité quand un prix est inférieur à un yuan."}},{"id":"convenience-store-run-vocab-10","hanzi":"小票","pinyin":"xiǎopiào","audio":"/audio/convenience-store-run/vocab-10.mp3","meaning":{"en":"receipt","fr":"ticket de caisse"},"explanation":{"en":"The small receipt you get after paying at a store.","fr":"Le petit reçu que tu obtiens après avoir payé en magasin."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(104, 'convenience-store-run', 'vocabulary', '[{"id":"convenience-store-run-vocab-1","hanzi":"一瓶水","pinyin":"yì píng shuǐ","audio":"/audio/convenience-store-run/vocab-01.mp3","meaning":{"en":"a bottle of water","fr":"une bouteille d''eau"},"explanation":{"en":"A useful first purchase item after arriving.","fr":"Un premier achat utile après l''arrivée."}},{"id":"convenience-store-run-vocab-2","hanzi":"还要别的吗","pinyin":"hái yào bié de ma","audio":"/audio/convenience-store-run/vocab-02.mp3","meaning":{"en":"anything else?","fr":"autre chose ?"},"explanation":{"en":"Listen for this checkout question after naming your item.","fr":"Écoute cette question à la caisse après avoir nommé ton article."}},{"id":"convenience-store-run-vocab-3","hanzi":"不要了","pinyin":"bú yào le","audio":"/audio/convenience-store-run/vocab-03.mp3","meaning":{"en":"no more / nothing else","fr":"rien d''autre"},"explanation":{"en":"Use it to say you do not need anything else.","fr":"Utilise-le pour dire que tu n''as besoin de rien d''autre."}},{"id":"convenience-store-run-vocab-4","hanzi":"一共","pinyin":"yígòng","audio":"/audio/convenience-store-run/vocab-04.mp3","meaning":{"en":"altogether / in total","fr":"au total"},"explanation":{"en":"This word prepares the total price question.","fr":"Ce mot prépare la question du prix total."}},{"id":"convenience-store-run-vocab-5","hanzi":"多少钱","pinyin":"duōshao qián","audio":"/audio/convenience-store-run/vocab-05.mp3","meaning":{"en":"how much money?","fr":"combien d''argent ? / combien ça coûte ?"},"explanation":{"en":"The key phrase for asking a simple price.","fr":"La phrase clé pour demander un prix simple."}},{"id":"convenience-store-run-vocab-6","hanzi":"薯片","pinyin":"shǔpiàn","audio":"/audio/convenience-store-run/vocab-06.mp3","meaning":{"en":"potato chips","fr":"chips"},"explanation":{"en":"A common snack to buy in convenience stores.","fr":"Un snack courant à acheter en supérette."}},{"id":"convenience-store-run-vocab-7","hanzi":"袋子","pinyin":"dàizi","audio":"/audio/convenience-store-run/vocab-07.mp3","meaning":{"en":"bag","fr":"sac"},"explanation":{"en":"Ask for a 袋子 if you need something to carry your items.","fr":"Demande un 袋子 si tu as besoin de porter tes articles."}},{"id":"convenience-store-run-vocab-8","hanzi":"扫码","pinyin":"sǎomǎ","audio":"/audio/convenience-store-run/vocab-08.mp3","meaning":{"en":"scan code / scan to pay","fr":"scanner le code / scanner pour payer"},"explanation":{"en":"The clerk points to the QR code and says this.","fr":"L''employé montre le code QR et dit ceci."}},{"id":"convenience-store-run-vocab-9","hanzi":"毛","pinyin":"máo","audio":"/audio/convenience-store-run/vocab-09.mp3","meaning":{"en":"dime / one-tenth of a yuan","fr":"dixième de yuan"},"explanation":{"en":"毛 is the smaller unit when a price is under one yuan.","fr":"毛 est la petite unité quand un prix est inférieur à un yuan."}},{"id":"convenience-store-run-vocab-10","hanzi":"小票","pinyin":"xiǎopiào","audio":"/audio/convenience-store-run/vocab-10.mp3","meaning":{"en":"receipt","fr":"ticket de caisse"},"explanation":{"en":"The small receipt you get after paying at a store.","fr":"Le petit reçu que tu obtiens après avoir payé en magasin."}}]', 'draft', 103, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(105, 'convenience-store-run', 'practice', '{"listening":[{"id":"convenience-store-run-listening-1","prompt":{"en":"Listen for the phrase that means a bottle of water.","fr":"Écoute la phrase qui signifie une bouteille d''eau."},"target":"一瓶水","audio":"/audio/convenience-store-run/practice-listening-01.mp3","explanation":{"en":"一瓶水 is the item you are buying.","fr":"一瓶水 est l''article que tu achètes."}},{"id":"convenience-store-run-listening-2","prompt":{"en":"Which phrase asks for a bag?","fr":"Quelle phrase demande un sac ?"},"target":"有袋子吗？","audio":"/audio/convenience-store-run/practice-listening-02.mp3","explanation":{"en":"有袋子吗 checks if the store provides bags.","fr":"有袋子吗 vérifie si le magasin fournit des sacs."}}],"speaking":[{"id":"convenience-store-run-speaking-1","prompt":{"en":"Say you do not need anything else.","fr":"Dis que tu n''as besoin de rien d''autre."},"target":"不要了。","audio":"/audio/convenience-store-run/practice-speaking-01.mp3","explanation":{"en":"不要了 answers the clerk''s \\"anything else?\\" question.","fr":"不要了 répond à la question « autre chose ? » de l''employé."}},{"id":"convenience-store-run-speaking-2","prompt":{"en":"Ask if they have a bag.","fr":"Demande s''ils ont un sac."},"target":"有袋子吗？","audio":"/audio/convenience-store-run/practice-speaking-02.mp3","explanation":{"en":"A short practical question when buying several items.","fr":"Une question pratique et courte quand on achète plusieurs articles."}}],"reading":[{"id":"convenience-store-run-reading-1","prompt":{"en":"Choose the phrase for asking the total price.","fr":"Choisis la phrase pour demander le prix total."},"target":"一共多少钱？","audio":"/audio/convenience-store-run/practice-reading-01.mp3","explanation":{"en":"一共多少钱？ asks how much the purchase costs altogether.","fr":"一共多少钱？ demande combien coûte l''achat au total."}},{"id":"convenience-store-run-reading-2","prompt":{"en":"Match the word for potato chips.","fr":"Associe le mot pour chips."},"target":"薯片","audio":"/audio/convenience-store-run/practice-reading-02.mp3","explanation":{"en":"薯片 is a common snack you will see on shelves.","fr":"薯片 est un snack courant que tu verras dans les rayons."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
