(109, 'ask-for-help-problem', 'lessonMeta', '{"id":"ask-for-help-problem","title":{"en":"寻求帮助 / Ask for help","fr":"寻求帮助 / Demander de l’aide"},"scenario":{"en":"When you need help in a public place, or something urgent has come up, those phrases come in handy.","fr":"Quand tu as besoin d’aide dans un lieu public, ou qu’un problème urgent survient, ces phrases sont bien utiles."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(110, 'ask-for-help-problem', 'lessonMeta', '{"id":"ask-for-help-problem","title":{"en":"寻求帮助 / Ask for help","fr":"寻求帮助 / Demander de l’aide"},"scenario":{"en":"When you need help in a public place, or something urgent has come up, those phrases come in handy.","fr":"Quand tu as besoin d’aide dans un lieu public, ou qu’un problème urgent survient, ces phrases sont bien utiles."}}', 'draft', 109, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(111, 'ask-for-help-problem', 'dialogue', '{"title":{"en":"Solve a phone problem and ask for practical help","fr":"Résoudre un problème de téléphone et demander une aide pratique"},"lines":[{"id":"ask-for-help-problem-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，可以帮我一下吗？","pinyin":"Nǐ hǎo, kěyǐ bāng wǒ yíxià ma?","translation":{"en":"Hello, could you help me for a moment?","fr":"Bonjour, pouvez-vous m’aider un instant ?"},"explanation":{"en":"可以帮我一下吗 is polite and short when you need help.","fr":"可以帮我一下吗 est poli et court quand tu as besoin d’aide."},"audio":"/audio/ask-for-help-problem/line-01.mp3"},{"id":"ask-for-help-problem-line-02","speaker":{"en":"Helper","fr":"Aide"},"hanzi":"怎么了？","pinyin":"Zěnme le?","translation":{"en":"What happened?","fr":"Qu’est-ce qui se passe ?"},"explanation":{"en":"This common question invites you to explain the problem.","fr":"Cette question courante t’invite à expliquer le problème."},"audio":"/audio/ask-for-help-problem/line-02.mp3"},{"id":"ask-for-help-problem-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我的手机有问题，不能支付。","pinyin":"Wǒ de shǒujī yǒu wèntí, bù néng zhīfù.","translation":{"en":"My phone has a problem and cannot pay.","fr":"Mon téléphone a un problème et ne peut pas payer."},"explanation":{"en":"我的……有问题 names the item; 不能支付 names the payment issue.","fr":"我的……有问题 nomme l’objet ; 不能支付 nomme le problème de paiement."},"audio":"/audio/ask-for-help-problem/line-03.mp3"},{"id":"ask-for-help-problem-line-04","speaker":{"en":"Helper","fr":"Aide"},"hanzi":"我帮你看一下。手机还有电吗？","pinyin":"Wǒ bāng nǐ kàn yíxià. Shǒujī hái yǒu diàn ma?","translation":{"en":"I''ll take a look. Does your phone still have battery?","fr":"Je vais regarder. Votre téléphone a-t-il encore de la batterie ?"},"explanation":{"en":"还有电吗 is a practical check before troubleshooting further.","fr":"还有电吗 est une vérification pratique avant de dépanner davantage."},"audio":"/audio/ask-for-help-problem/line-04.mp3"},{"id":"ask-for-help-problem-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"快没电了。这里有无线网吗？","pinyin":"Kuài méi diàn le. Zhèlǐ yǒu wúxiànwǎng ma?","translation":{"en":"Almost out of battery. Is there WiFi here?","fr":"Presque plus de batterie. Y a-t-il du WiFi ici ?"},"explanation":{"en":"快没电了 warns about low battery; 无线网 asks for a WiFi connection.","fr":"快没电了 avertit que la batterie est faible ; 无线网 demande une connexion WiFi."},"audio":"/audio/ask-for-help-problem/line-05.mp3"},{"id":"ask-for-help-problem-line-06","speaker":{"en":"Helper","fr":"Aide"},"hanzi":"有，密码在那边。可以充电吗？","pinyin":"Yǒu, mìmǎ zài nàbiān. Kěyǐ chōngdiàn ma?","translation":{"en":"Yes, the password is over there. Can you charge your phone?","fr":"Oui, le mot de passe est là-bas. Pouvez-vous recharger votre téléphone ?"},"explanation":{"en":"密码 in 那边 is a common response; 充电 asks if you can plug in.","fr":"密码在那边 est une réponse courante ; 充电 demande si tu peux brancher."},"audio":"/audio/ask-for-help-problem/line-06.mp3"},{"id":"ask-for-help-problem-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"可以，可是我没有充电器。","pinyin":"Kěyǐ, kěshì wǒ méiyǒu chōngdiànqì.","translation":{"en":"Yes I can, but I don''t have a charger.","fr":"Oui je peux, mais je n''ai pas de chargeur."},"explanation":{"en":"可是 introduces a new obstacle in the help exchange.","fr":"可是 introduit un nouvel obstacle dans l''échange d''aide."},"audio":"/audio/ask-for-help-problem/line-07.mp3"},{"id":"ask-for-help-problem-line-08","speaker":{"en":"Helper","fr":"Aide"},"hanzi":"没关系，我这里有。请慢一点说，不着急。","pinyin":"Méi guānxi, wǒ zhèlǐ yǒu. Qǐng màn yìdiǎn shuō, bù zháojí.","translation":{"en":"No problem, I have one here. Please speak more slowly, no rush.","fr":"Pas de problème, j''en ai un ici. Parlez un peu plus lentement, sans vous presser."},"explanation":{"en":"没关系 keeps the tone friendly; the helper also encourages slower speech.","fr":"没关系 garde un ton amical ; la personne encourage aussi une parole plus lente."},"audio":"/audio/ask-for-help-problem/line-08.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
