(115, 'ask-for-help-problem', 'vocabulary', '[{"id":"ask-for-help-problem-vocab-1","hanzi":"帮忙","pinyin":"bāngmáng","audio":"/audio/ask-for-help-problem/vocab-01.mp3","meaning":{"en":"help","fr":"aide / aider"},"explanation":{"en":"The core idea behind 帮我一下.","fr":"L’idée centrale derrière 帮我一下."}},{"id":"ask-for-help-problem-vocab-2","hanzi":"问题","pinyin":"wèntí","audio":"/audio/ask-for-help-problem/vocab-02.mp3","meaning":{"en":"problem / question","fr":"problème / question"},"explanation":{"en":"Use 有问题 to say something is wrong.","fr":"Utilise 有问题 pour dire que quelque chose ne va pas."}},{"id":"ask-for-help-problem-vocab-3","hanzi":"手机","pinyin":"shǒujī","audio":"/audio/ask-for-help-problem/vocab-03.mp3","meaning":{"en":"phone","fr":"téléphone"},"explanation":{"en":"The object with the problem in this scenario.","fr":"L’objet qui a un problème dans cette situation."}},{"id":"ask-for-help-problem-vocab-4","hanzi":"不能","pinyin":"bù néng","audio":"/audio/ask-for-help-problem/vocab-04.mp3","meaning":{"en":"cannot","fr":"ne pas pouvoir"},"explanation":{"en":"Use it before a blocked action like 支付.","fr":"Utilise-le avant une action bloquée comme 支付."}},{"id":"ask-for-help-problem-vocab-5","hanzi":"慢一点","pinyin":"màn yìdiǎn","audio":"/audio/ask-for-help-problem/vocab-05.mp3","meaning":{"en":"a little slower","fr":"un peu plus lentement"},"explanation":{"en":"A repair phrase for understanding spoken Chinese.","fr":"Une phrase de réparation pour comprendre le chinois parlé."}},{"id":"ask-for-help-problem-vocab-6","hanzi":"没电","pinyin":"méi diàn","audio":"/audio/ask-for-help-problem/vocab-06.mp3","meaning":{"en":"out of battery / no power","fr":"plus de batterie / pas d''électricité"},"explanation":{"en":"The key phrase for a dead phone or device.","fr":"La phrase clé pour un téléphone ou un appareil déchargé."}},{"id":"ask-for-help-problem-vocab-7","hanzi":"无线网","pinyin":"wúxiànwǎng","audio":"/audio/ask-for-help-problem/vocab-07.mp3","meaning":{"en":"WiFi / wireless network","fr":"WiFi / réseau sans fil"},"explanation":{"en":"A common word for WiFi you will see on signs.","fr":"Un mot courant pour le WiFi que tu verras sur les panneaux."}},{"id":"ask-for-help-problem-vocab-8","hanzi":"密码","pinyin":"mìmǎ","audio":"/audio/ask-for-help-problem/vocab-08.mp3","meaning":{"en":"password / PIN","fr":"mot de passe / code"},"explanation":{"en":"You will hear this when asking for WiFi access.","fr":"Tu entendras ce mot en demandant l''accès au WiFi."}},{"id":"ask-for-help-problem-vocab-9","hanzi":"充电","pinyin":"chōngdiàn","audio":"/audio/ask-for-help-problem/vocab-09.mp3","meaning":{"en":"charge / recharge","fr":"charger / recharger"},"explanation":{"en":"The action to restore battery power.","fr":"L''action pour restaurer la batterie."}},{"id":"ask-for-help-problem-vocab-10","hanzi":"没关系","pinyin":"méi guānxi","audio":"/audio/ask-for-help-problem/vocab-10.mp3","meaning":{"en":"no problem / it doesn''t matter","fr":"pas de problème / ce n''est pas grave"},"explanation":{"en":"A friendly phrase to keep the help exchange relaxed.","fr":"Une phrase amicale pour garder l''échange d''aide détendu."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(116, 'ask-for-help-problem', 'vocabulary', '[{"id":"ask-for-help-problem-vocab-1","hanzi":"帮忙","pinyin":"bāngmáng","audio":"/audio/ask-for-help-problem/vocab-01.mp3","meaning":{"en":"help","fr":"aide / aider"},"explanation":{"en":"The core idea behind 帮我一下.","fr":"L’idée centrale derrière 帮我一下."}},{"id":"ask-for-help-problem-vocab-2","hanzi":"问题","pinyin":"wèntí","audio":"/audio/ask-for-help-problem/vocab-02.mp3","meaning":{"en":"problem / question","fr":"problème / question"},"explanation":{"en":"Use 有问题 to say something is wrong.","fr":"Utilise 有问题 pour dire que quelque chose ne va pas."}},{"id":"ask-for-help-problem-vocab-3","hanzi":"手机","pinyin":"shǒujī","audio":"/audio/ask-for-help-problem/vocab-03.mp3","meaning":{"en":"phone","fr":"téléphone"},"explanation":{"en":"The object with the problem in this scenario.","fr":"L’objet qui a un problème dans cette situation."}},{"id":"ask-for-help-problem-vocab-4","hanzi":"不能","pinyin":"bù néng","audio":"/audio/ask-for-help-problem/vocab-04.mp3","meaning":{"en":"cannot","fr":"ne pas pouvoir"},"explanation":{"en":"Use it before a blocked action like 支付.","fr":"Utilise-le avant une action bloquée comme 支付."}},{"id":"ask-for-help-problem-vocab-5","hanzi":"慢一点","pinyin":"màn yìdiǎn","audio":"/audio/ask-for-help-problem/vocab-05.mp3","meaning":{"en":"a little slower","fr":"un peu plus lentement"},"explanation":{"en":"A repair phrase for understanding spoken Chinese.","fr":"Une phrase de réparation pour comprendre le chinois parlé."}},{"id":"ask-for-help-problem-vocab-6","hanzi":"没电","pinyin":"méi diàn","audio":"/audio/ask-for-help-problem/vocab-06.mp3","meaning":{"en":"out of battery / no power","fr":"plus de batterie / pas d''électricité"},"explanation":{"en":"The key phrase for a dead phone or device.","fr":"La phrase clé pour un téléphone ou un appareil déchargé."}},{"id":"ask-for-help-problem-vocab-7","hanzi":"无线网","pinyin":"wúxiànwǎng","audio":"/audio/ask-for-help-problem/vocab-07.mp3","meaning":{"en":"WiFi / wireless network","fr":"WiFi / réseau sans fil"},"explanation":{"en":"A common word for WiFi you will see on signs.","fr":"Un mot courant pour le WiFi que tu verras sur les panneaux."}},{"id":"ask-for-help-problem-vocab-8","hanzi":"密码","pinyin":"mìmǎ","audio":"/audio/ask-for-help-problem/vocab-08.mp3","meaning":{"en":"password / PIN","fr":"mot de passe / code"},"explanation":{"en":"You will hear this when asking for WiFi access.","fr":"Tu entendras ce mot en demandant l''accès au WiFi."}},{"id":"ask-for-help-problem-vocab-9","hanzi":"充电","pinyin":"chōngdiàn","audio":"/audio/ask-for-help-problem/vocab-09.mp3","meaning":{"en":"charge / recharge","fr":"charger / recharger"},"explanation":{"en":"The action to restore battery power.","fr":"L''action pour restaurer la batterie."}},{"id":"ask-for-help-problem-vocab-10","hanzi":"没关系","pinyin":"méi guānxi","audio":"/audio/ask-for-help-problem/vocab-10.mp3","meaning":{"en":"no problem / it doesn''t matter","fr":"pas de problème / ce n''est pas grave"},"explanation":{"en":"A friendly phrase to keep the help exchange relaxed.","fr":"Une phrase amicale pour garder l''échange d''aide détendu."}}]', 'draft', 115, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(117, 'ask-for-help-problem', 'practice', '{"listening":[{"id":"ask-for-help-problem-listening-1","prompt":{"en":"Listen for the sentence that says the phone has a problem.","fr":"Écoute la phrase qui dit que le téléphone a un problème."},"target":"我的手机有问题，不能支付。","audio":"/audio/ask-for-help-problem/practice-listening-01.mp3","explanation":{"en":"This is the key explanation after asking for help.","fr":"C’est l’explication clé après la demande d’aide."}},{"id":"ask-for-help-problem-listening-2","prompt":{"en":"Which phrase warns about low battery?","fr":"Quelle phrase avertit d''une batterie faible ?"},"target":"快没电了。","audio":"/audio/ask-for-help-problem/practice-listening-02.mp3","explanation":{"en":"快没电了 is the warning you say or hear when battery is low.","fr":"快没电了 est l''avertissement que tu dis ou entends quand la batterie est faible."}}],"speaking":[{"id":"ask-for-help-problem-speaking-1","prompt":{"en":"Ask someone to help you for a moment.","fr":"Demande à quelqu’un de t’aider un instant."},"target":"可以帮我一下吗？","audio":"/audio/ask-for-help-problem/practice-speaking-01.mp3","explanation":{"en":"Open with the polite request before explaining the issue.","fr":"Commence par la demande polie avant d’expliquer le problème."}},{"id":"ask-for-help-problem-speaking-2","prompt":{"en":"Ask if there is WiFi here.","fr":"Demande s''il y a du WiFi ici."},"target":"这里有WiFi吗？","audio":"/audio/ask-for-help-problem/practice-speaking-02.mp3","explanation":{"en":"A practical question when you need internet access.","fr":"Une question pratique quand tu as besoin d''accès internet."}}],"reading":[{"id":"ask-for-help-problem-reading-1","prompt":{"en":"Read the slower-speech request.","fr":"Lis la demande de parler plus lentement."},"target":"请慢一点说。","audio":"/audio/ask-for-help-problem/practice-reading-01.mp3","explanation":{"en":"This helps you keep the conversation understandable.","fr":"Cela t’aide à garder la conversation compréhensible."}},{"id":"ask-for-help-problem-reading-2","prompt":{"en":"Match the phrase for \\"no problem\\".","fr":"Associe la phrase pour \\"pas de problème\\"."},"target":"没关系","audio":"/audio/ask-for-help-problem/practice-reading-02.mp3","explanation":{"en":"没关系 is a friendly go-to reply in many situations.","fr":"没关系 est une réponse amicale passe-partout dans de nombreuses situations."}}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(118, 'ask-for-help-problem', 'practice', '{"listening":[{"id":"ask-for-help-problem-listening-1","prompt":{"en":"Listen for the sentence that says the phone has a problem.","fr":"Écoute la phrase qui dit que le téléphone a un problème."},"target":"我的手机有问题，不能支付。","audio":"/audio/ask-for-help-problem/practice-listening-01.mp3","explanation":{"en":"This is the key explanation after asking for help.","fr":"C’est l’explication clé après la demande d’aide."}},{"id":"ask-for-help-problem-listening-2","prompt":{"en":"Which phrase warns about low battery?","fr":"Quelle phrase avertit d''une batterie faible ?"},"target":"快没电了。","audio":"/audio/ask-for-help-problem/practice-listening-02.mp3","explanation":{"en":"快没电了 is the warning you say or hear when battery is low.","fr":"快没电了 est l''avertissement que tu dis ou entends quand la batterie est faible."}}],"speaking":[{"id":"ask-for-help-problem-speaking-1","prompt":{"en":"Ask someone to help you for a moment.","fr":"Demande à quelqu’un de t’aider un instant."},"target":"可以帮我一下吗？","audio":"/audio/ask-for-help-problem/practice-speaking-01.mp3","explanation":{"en":"Open with the polite request before explaining the issue.","fr":"Commence par la demande polie avant d’expliquer le problème."}},{"id":"ask-for-help-problem-speaking-2","prompt":{"en":"Ask if there is WiFi here.","fr":"Demande s''il y a du WiFi ici."},"target":"这里有WiFi吗？","audio":"/audio/ask-for-help-problem/practice-speaking-02.mp3","explanation":{"en":"A practical question when you need internet access.","fr":"Une question pratique quand tu as besoin d''accès internet."}}],"reading":[{"id":"ask-for-help-problem-reading-1","prompt":{"en":"Read the slower-speech request.","fr":"Lis la demande de parler plus lentement."},"target":"请慢一点说。","audio":"/audio/ask-for-help-problem/practice-reading-01.mp3","explanation":{"en":"This helps you keep the conversation understandable.","fr":"Cela t’aide à garder la conversation compréhensible."}},{"id":"ask-for-help-problem-reading-2","prompt":{"en":"Match the phrase for \\"no problem\\".","fr":"Associe la phrase pour \\"pas de problème\\"."},"target":"没关系","audio":"/audio/ask-for-help-problem/practice-reading-02.mp3","explanation":{"en":"没关系 is a friendly go-to reply in many situations.","fr":"没关系 est une réponse amicale passe-partout dans de nombreuses situations."}}]}', 'draft', 117, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(119, 'ask-for-help-problem', 'reviewCards', '[{"id":"ask-for-help-problem-review-1","front":"帮我一下","back":{"en":"help me for a moment","fr":"aidez-moi un instant"},"explanation":{"en":"A polite core help request.","fr":"Une demande d’aide centrale et polie."}},{"id":"ask-for-help-problem-review-2","front":"有问题","back":{"en":"has a problem","fr":"a un problème"},"explanation":{"en":"Use it after the item with the issue.","fr":"Utilise-le après l’objet qui pose problème."}},{"id":"ask-for-help-problem-review-3","front":"慢一点","back":{"en":"a little slower","fr":"un peu plus lentement"},"explanation":{"en":"A repair phrase when speech is too fast.","fr":"Une phrase de réparation si la parole est trop rapide."}},{"id":"ask-for-help-problem-review-4","front":"没电","back":{"en":"out of battery","fr":"plus de batterie"},"explanation":{"en":"Say this when your phone is dead.","fr":"Dis ceci quand ton téléphone est déchargé."}},{"id":"ask-for-help-problem-review-5","front":"密码","back":{"en":"password","fr":"mot de passe"},"explanation":{"en":"Ask for this when connecting to WiFi.","fr":"Demande ceci pour te connecter au WiFi."}},{"id":"ask-for-help-problem-review-6","front":"没关系","back":{"en":"no problem","fr":"pas de problème"},"explanation":{"en":"A friendly reply that keeps the exchange relaxed.","fr":"Une réponse amicale qui garde l''échange détendu."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
