(121, 'pharmacy-help', 'lessonMeta', '{"id":"pharmacy-help","title":{"en":"买药，看医生 / Hospital and pharmacy","fr":"买药，看医生 / Hôpital et pharmacie"},"scenario":{"en":"Describe your discomfort and get the right treatment or medicine.","fr":"Décris ton inconfort et obtiens le bon traitement ou le bon médicament."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(122, 'pharmacy-help', 'lessonMeta', '{"id":"pharmacy-help","title":{"en":"买药，看医生 / Hospital and pharmacy","fr":"买药，看医生 / Hôpital et pharmacie"},"scenario":{"en":"Describe your discomfort and get the right treatment or medicine.","fr":"Décris ton inconfort et obtiens le bon traitement ou le bon médicament."}}', 'draft', 121, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(123, 'pharmacy-help', 'dialogue', '{"title":{"en":"Describe symptoms and buy medicine","fr":"Décrire des symptômes et acheter un médicament"},"lines":[{"id":"pharmacy-help-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好，我头疼。","pinyin":"Nǐ hǎo, wǒ tóu téng.","translation":{"en":"Hello, my head hurts.","fr":"Bonjour, j’ai mal à la tête."},"explanation":{"en":"我……疼 is a simple way to name a mild pain.","fr":"我……疼 est une façon simple de nommer une douleur légère."},"audio":"/audio/pharmacy-help/line-01.mp3"},{"id":"pharmacy-help-line-02","speaker":{"en":"Pharmacist","fr":"Pharmacien"},"hanzi":"你发烧吗？","pinyin":"Nǐ fāshāo ma?","translation":{"en":"Do you have a fever?","fr":"Avez-vous de la fièvre ?"},"explanation":{"en":"The clerk asks a yes/no symptom question with 吗.","fr":"Le pharmacien pose une question oui/non sur un symptôme avec 吗."},"audio":"/audio/pharmacy-help/line-02.mp3"},{"id":"pharmacy-help-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"不发烧，但是肚子也有点疼。","pinyin":"Bù fāshāo, dànshì dùzi yě yǒudiǎn téng.","translation":{"en":"No fever, but my stomach also hurts a little.","fr":"Pas de fièvre, mais j’ai aussi un peu mal au ventre."},"explanation":{"en":"Add 但是 to link two symptoms in one turn.","fr":"Ajoute 但是 pour relier deux symptômes en une seule réplique."},"audio":"/audio/pharmacy-help/line-03.mp3"},{"id":"pharmacy-help-line-04","speaker":{"en":"Pharmacist","fr":"Pharmacien"},"hanzi":"你对什么过敏吗？","pinyin":"Nǐ duì shénme guòmǐn ma?","translation":{"en":"Are you allergic to anything?","fr":"Êtes-vous allergique à quelque chose ?"},"explanation":{"en":"A safety question the pharmacist will ask before giving medicine.","fr":"Une question de sécurité que le pharmacien pose avant de donner un médicament."},"audio":"/audio/pharmacy-help/line-04.mp3"},{"id":"pharmacy-help-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"没有过敏。","pinyin":"Méiyǒu guòmǐn.","translation":{"en":"No allergies.","fr":"Pas d’allergie."},"explanation":{"en":"A short clear answer to the allergy safety question.","fr":"Une réponse courte et claire à la question de sécurité sur les allergies."},"audio":"/audio/pharmacy-help/line-05.mp3"},{"id":"pharmacy-help-line-06","speaker":{"en":"Pharmacist","fr":"Pharmacien"},"hanzi":"这个止疼药，一次一片，一天两次。","pinyin":"Zhège zhǐténg yào, yí cì yí piàn, yì tiān liǎng cì.","translation":{"en":"This painkiller, one tablet per dose, twice a day.","fr":"Cet antidouleur, un comprimé par prise, deux fois par jour."},"explanation":{"en":"一次一片 adds the dosage detail on top of the frequency.","fr":"一次一片 ajoute le détail du dosage en plus de la fréquence."},"audio":"/audio/pharmacy-help/line-06.mp3"},{"id":"pharmacy-help-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"饭前吃还是饭后吃？","pinyin":"Fàn qián chī háishi fàn hòu chī?","translation":{"en":"Take before or after meals?","fr":"Prendre avant ou après les repas ?"},"explanation":{"en":"饭前/饭后 is a common instruction to check for any medicine.","fr":"饭前/饭后 est une consigne courante à vérifier pour tout médicament."},"audio":"/audio/pharmacy-help/line-07.mp3"},{"id":"pharmacy-help-line-08","speaker":{"en":"Pharmacist","fr":"Pharmacien"},"hanzi":"饭后吃。一共十八块钱。","pinyin":"Fàn hòu chī. Yígòng shíbā kuài qián.","translation":{"en":"After meals. Eighteen yuan altogether.","fr":"Après les repas. Dix-huit yuans au total."},"explanation":{"en":"The pharmacist gives the instruction and the price together.","fr":"Le pharmacien donne la consigne et le prix ensemble."},"audio":"/audio/pharmacy-help/line-08.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
