ion":{"en":"A short clear answer to the allergy safety question.","fr":"Une réponse courte et claire à la question de sécurité sur les allergies."},"audio":"/audio/pharmacy-help/line-05.mp3"},{"id":"pharmacy-help-line-06","speaker":{"en":"Pharmacist","fr":"Pharmacien"},"hanzi":"这个止疼药，一次一片，一天两次。","pinyin":"Zhège zhǐténg yào, yí cì yí piàn, yì tiān liǎng cì.","translation":{"en":"This painkiller, one tablet per dose, twice a day.","fr":"Cet antidouleur, un comprimé par prise, deux fois par jour."},"explanation":{"en":"一次一片 adds the dosage detail on top of the frequency.","fr":"一次一片 ajoute le détail du dosage en plus de la fréquence."},"audio":"/audio/pharmacy-help/line-06.mp3"},{"id":"pharmacy-help-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"饭前吃还是饭后吃？","pinyin":"Fàn qián chī háishi fàn hòu chī?","translation":{"en":"Take before or after meals?","fr":"Prendre avant ou après les repas ?"},"explanation":{"en":"饭前/饭后 is a common instruction to check for any medicine.","fr":"饭前/饭后 est une consigne courante à vérifier pour tout médicament."},"audio":"/audio/pharmacy-help/line-07.mp3"},{"id":"pharmacy-help-line-08","speaker":{"en":"Pharmacist","fr":"Pharmacien"},"hanzi":"饭后吃。一共十八块钱。","pinyin":"Fàn hòu chī. Yígòng shíbā kuài qián.","translation":{"en":"After meals. Eighteen yuan altogether.","fr":"Après les repas. Dix-huit yuans au total."},"explanation":{"en":"The pharmacist gives the instruction and the price together.","fr":"Le pharmacien donne la consigne et le prix ensemble."},"audio":"/audio/pharmacy-help/line-08.mp3"}]}', 'draft', 123, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(125, 'pharmacy-help', 'sentencePatterns', '[{"id":"pharmacy-help-pattern-1","pattern":"请问哪里有……？","meaning":{"en":"Where is the ...?","fr":"Où est ... ?"},"example":"请问哪里有医院？","audio":"/audio/pharmacy-help/pattern-01.mp3","explanation":{"en":"Use 哪里有 to ask where a place like a hospital or pharmacy is.","fr":"Utilise 哪里有 pour demander où se trouve un lieu comme un hôpital ou une pharmacie."}},{"id":"pharmacy-help-pattern-2","pattern":"我……疼。","meaning":{"en":"My ... hurts.","fr":"J’ai mal à ..."},"example":"我肚子疼。","audio":"/audio/pharmacy-help/pattern-02.mp3","explanation":{"en":"Put the body part before 疼 to describe where it hurts.","fr":"Place la partie du corps avant 疼 pour décrire où tu as mal."}},{"id":"pharmacy-help-pattern-3","pattern":"我……了。","meaning":{"en":"I have ...","fr":"J’ai ..."},"example":"我发烧了。","audio":"/audio/pharmacy-help/pattern-03.mp3","explanation":{"en":"Use 我……了 to state a symptom like a fever, cold, or diarrhea.","fr":"Utilise 我……了 pour indiquer un symptôme comme la fièvre, un rhume ou la diarrhée."}},{"id":"pharmacy-help-pattern-4","pattern":"我想买……。","meaning":{"en":"I want to buy ...","fr":"Je veux acheter ..."},"example":"我想买药。","audio":"/audio/pharmacy-help/pattern-04.mp3","explanation":{"en":"Use 我想买 to ask for medicine at a pharmacy.","fr":"Utilise 我想买 pour demander un médicament à la pharmacie."}},{"id":"pharmacy-help-pattern-5","pattern":"饭前吃还是饭后吃？","meaning":{"en":"Should I take it before or after meals?","fr":"Dois-je le prendre avant ou après les repas ?"},"example":"饭前吃还是饭后吃？","audio":"/audio/pharmacy-help/pattern-05.mp3","explanation":{"en":"Ask this to confirm when to take your medicine.","fr":"Demande ceci pour confirmer quand prendre ton médicament."}},{"id":"pharmacy-help-pattern-6","pattern":"我要挂号。","meaning":{"en":"I need to register.","fr":"Je dois m''inscrire / enregistrer."},"example":"我要挂号。","audio":"/audio/pharmacy-help/pattern-06.mp3","explanation":{"en":"Say 我要挂号 to register at a hospital reception.","fr":"Dis 我要挂号 pour t''inscrire à l''accueil de l''hôpital."}},{"id":"pharmacy-help-pattern-7","pattern":"我头痛。","meaning":{"en":"I have a headache.","fr":"J''ai mal à la tête."},"example":"我头痛。","audio":"/audio/pharmacy-help/pattern-07.mp3","explanation":{"en":"Describe a headache with 我头痛.","fr":"Décris un mal de tête avec 我头痛."}},{"id":"pharmacy-help-pattern-8","pattern":"我感冒了。","meaning":{"en":"I caught a cold.","fr":"J''ai attrapé un rhume."},"example":"我感冒了。","audio":"/audio/pharmacy-help/pattern-08.mp3","explanation":{"en":"Say 我感冒了 to tell the doctor or pharmacist you have a cold.","fr":"Dis 我感冒了 pour dire au médecin ou au pharmacien que tu as un rhume."}},{"id":"pharmacy-help-pattern-9","pattern":"我拉肚子了。","meaning":{"en":"I have diarrhea.","fr":"J''ai la diarrhée."},"example":"我拉肚子了。","audio":"/audio/pharmacy-help/pattern-09.mp3","explanation":{"en":"Report a stomach problem with 我拉肚子了.","fr":"Signale un problème de ventre avec 我拉肚子了."}},{"id":"pharmacy-help-pattern-10","pattern":"谢谢医生。谢谢护士。","meaning":{"en":"Thank you, doctor. Thank you, nurse.","fr":"Merci, docteur. Merci, infirmière."},"example":"谢谢医生。谢谢护士。","audio":"/audio/pharmacy-help/pattern-10.mp3","explanation":{"en":"Thank the medical staff with 谢谢医生 and 谢谢护士.","fr":"Remercie le personnel médical avec 谢谢医生 et 谢谢护士."}},{"id":"pharmacy-help-pattern-11","pattern":"请问去哪里结账？","meaning":{"en":"Where do I pay the bill?","fr":"Où dois-je payer la facture ?"},"example":"请问去哪里结账？","audio":"/audio/pharmacy-help/pattern-11.mp3","explanation":{"en":"Ask 请问去哪里结账 to find the payment counter.","fr":"Demande 请问去哪里结账 pour trouver la caisse."}},{"id":"pharmacy-help-pattern-12","pattern":"去哪里取药？","meaning":{"en":"Where do I pick up my prescription?","fr":"Où retirer mon médicament ?"},"example":"去哪里取药？","audio":"/audio/pharmacy-help/pattern-12.mp3","explanation":{"en":"Ask 去哪里取药 to find where to collect your medicine.","fr":"Demande 去哪里取药 pour savoir où récupérer ton médicament."}},{"id":"pharmacy-help-pattern-13","pattern":"多少钱？","meaning":{"en":"How much is it?","fr":"Combien ça coûte ?"},"example":"多少钱？","audio":"/audio/pharmacy-help/pattern-13.mp3","explanation":{"en":"Ask 多少钱 to check the price of medicine or treatment.","fr":"Demande 多少钱 pour connaître le prix du médicament ou du traitement."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
