,"meaning":{"en":"How much is it?","fr":"Combien ça coûte ?"},"example":"多少钱？","audio":"/audio/pharmacy-help/pattern-13.mp3","explanation":{"en":"Ask 多少钱 to check the price of medicine or treatment.","fr":"Demande 多少钱 pour connaître le prix du médicament ou du traitement."}}]', 'draft', 125, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(127, 'pharmacy-help', 'vocabulary', '[{"id":"pharmacy-help-vocab-1","hanzi":"药店","pinyin":"yàodiàn","audio":"/audio/pharmacy-help/vocab-01.mp3","meaning":{"en":"pharmacy","fr":"pharmacie"},"explanation":{"en":"The place to ask for simple medicine help.","fr":"Le lieu pour demander une aide simple avec un médicament."}},{"id":"pharmacy-help-vocab-2","hanzi":"药","pinyin":"yào","audio":"/audio/pharmacy-help/vocab-02.mp3","meaning":{"en":"medicine","fr":"médicament"},"explanation":{"en":"A core word in pharmacy instructions.","fr":"Un mot essentiel dans les consignes de pharmacie."}},{"id":"pharmacy-help-vocab-3","hanzi":"头疼","pinyin":"tóu téng","audio":"/audio/pharmacy-help/vocab-03.mp3","meaning":{"en":"headache","fr":"mal à la tête"},"explanation":{"en":"The mild symptom used in the dialogue.","fr":"Le symptôme léger utilisé dans le dialogue."}},{"id":"pharmacy-help-vocab-4","hanzi":"发烧","pinyin":"fāshāo","audio":"/audio/pharmacy-help/vocab-04.mp3","meaning":{"en":"to have a fever","fr":"avoir de la fièvre"},"explanation":{"en":"A common follow-up symptom question.","fr":"Une question de symptôme fréquente."}},{"id":"pharmacy-help-vocab-5","hanzi":"过敏","pinyin":"guòmǐn","audio":"/audio/pharmacy-help/vocab-05.mp3","meaning":{"en":"allergy / allergic","fr":"allergie / allergique"},"explanation":{"en":"A safety word to recognize even in a mild-health lesson.","fr":"Un mot de sécurité à reconnaître même dans une leçon de santé légère."}},{"id":"pharmacy-help-vocab-6","hanzi":"肚子疼","pinyin":"dùzi téng","audio":"/audio/pharmacy-help/vocab-06.mp3","meaning":{"en":"stomach ache","fr":"mal au ventre"},"explanation":{"en":"Another common symptom to report at the pharmacy.","fr":"Un autre symptôme courant à signaler à la pharmacie."}},{"id":"pharmacy-help-vocab-7","hanzi":"止疼药","pinyin":"zhǐténg yào","audio":"/audio/pharmacy-help/vocab-07.mp3","meaning":{"en":"painkiller","fr":"antidouleur"},"explanation":{"en":"The kind of medicine you might ask for with a headache.","fr":"Le type de médicament que tu pourrais demander pour un mal de tête."}},{"id":"pharmacy-help-vocab-8","hanzi":"一次一片","pinyin":"yí cì yí piàn","audio":"/audio/pharmacy-help/vocab-08.mp3","meaning":{"en":"one tablet per dose","fr":"un comprimé par prise"},"explanation":{"en":"The dosage instruction you will hear with medicine.","fr":"La consigne de dosage que tu entendras avec le médicament."}},{"id":"pharmacy-help-vocab-9","hanzi":"饭前","pinyin":"fàn qián","audio":"/audio/pharmacy-help/vocab-09.mp3","meaning":{"en":"before meals","fr":"avant les repas"},"explanation":{"en":"One of the two common medicine timing words.","fr":"Un des deux mots courants pour le moment de prise du médicament."}},{"id":"pharmacy-help-vocab-10","hanzi":"饭后","pinyin":"fàn hòu","audio":"/audio/pharmacy-help/vocab-10.mp3","meaning":{"en":"after meals","fr":"après les repas"},"explanation":{"en":"The other common medicine timing word paired with 饭前.","fr":"L’autre mot courant pour le moment de prise, associé à 饭前."}},{"id":"pharmacy-help-vocab-11","hanzi":"医院","pinyin":"yīyuàn","audio":"/audio/pharmacy-help/vocab-11.mp3","meaning":{"en":"hospital","fr":"hôpital"},"explanation":{"en":"The place where you see a doctor or go to a pharmacy.","fr":"Le lieu où tu vois un médecin ou tu vas à la pharmacie."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
