(133, 'small-talk', 'lessonMeta', '{"id":"small-talk","title":{"en":"闲聊和赞美 / Small talk and compliment","fr":"闲聊和赞美 / Petite conversation et compliments"},"scenario":{"en":"Break the ice with common conversation starters and send positive messages by giving people proper compliments.","fr":"Brise la glace avec des amorces de conversation courantes et envoie des messages positifs en faisant des compliments appropriés."}}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(134, 'small-talk', 'lessonMeta', '{"id":"small-talk","title":{"en":"闲聊和赞美 / Small talk and compliment","fr":"闲聊和赞美 / Petite conversation et compliments"},"scenario":{"en":"Break the ice with common conversation starters and send positive messages by giving people proper compliments.","fr":"Brise la glace avec des amorces de conversation courantes et envoie des messages positifs en faisant des compliments appropriés."}}', 'draft', 133, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(135, 'small-talk', 'dialogue', '{"title":{"en":"A friendly chat","fr":"Une conversation amicale"},"lines":[{"id":"small-talk-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好！很高兴认识你。","pinyin":"Nǐ hǎo! Hěn gāoxìng rènshi nǐ.","translation":{"en":"Hello! Nice to meet you.","fr":"Bonjour ! Enchanté de faire votre connaissance."},"explanation":{"en":"Open the chat with a friendly greeting and 很高兴认识你.","fr":"Ouvrez la conversation avec une salutation amicale et 很高兴认识你."},"audio":"/audio/small-talk/line-01.mp3"},{"id":"small-talk-line-02","speaker":{"en":"Friend","fr":"Ami"},"hanzi":"你好！你是哪里人？","pinyin":"Nǐ hǎo! Nǐ shì nǎlǐ rén?","translation":{"en":"Hello! Where are you from?","fr":"Bonjour ! D’où venez-vous ?"},"explanation":{"en":"你是哪里人 is the classic small-talk question about where someone is from.","fr":"你是哪里人 est la question classique de petite conversation sur l’origine de quelqu’un."},"audio":"/audio/small-talk/line-02.mp3"},{"id":"small-talk-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我是法国人。你是本地人吗？","pinyin":"Wǒ shì Fǎguó rén. Nǐ shì běndì rén ma?","translation":{"en":"I am French. Are you local?","fr":"Je suis français. Êtes-vous d’ici ?"},"explanation":{"en":"我是…人 states your nationality, and …吗 turns the next sentence into a question.","fr":"我是…人 indique votre nationalité, et …吗 transforme la phrase en question."},"audio":"/audio/small-talk/line-03.mp3"},{"id":"small-talk-line-04","speaker":{"en":"Friend","fr":"Ami"},"hanzi":"是的，我是上海人。这里的天气怎么样？","pinyin":"Shì de, wǒ shì Shànghǎi rén. Zhèlǐ de tiānqì zěnme yàng?","translation":{"en":"Yes, I am from Shanghai. How is the weather here?","fr":"Oui, je suis de Shanghai. Quel temps fait-il ici ?"},"explanation":{"en":"天气怎么样 asks about the weather, a safe topic for small talk.","fr":"天气怎么样 demande le temps qu’il fait, un sujet sûr pour la petite conversation."},"audio":"/audio/small-talk/line-04.mp3"},{"id":"small-talk-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"天气很好！你们这里的东西很好吃。","pinyin":"Tiānqì hěn hǎo! Nǐmen zhèlǐ de dōngxi hěn hǎochī.","translation":{"en":"The weather is great! The food here is delicious.","fr":"Il fait beau ! La nourriture ici est délicieuse."},"explanation":{"en":"Complement the weather and local food to keep the chat going.","fr":"Complimentez le temps et la cuisine locale pour poursuivre la conversation."},"audio":"/audio/small-talk/line-05.mp3"},{"id":"small-talk-line-06","speaker":{"en":"Friend","fr":"Ami"},"hanzi":"你计划在这里待多久？","pinyin":"Nǐ jìhuà zài zhèlǐ dāi duōjiǔ?","translation":{"en":"How long do you plan to stay here?","fr":"Combien de temps comptez-vous rester ici ?"},"explanation":{"en":"计划在这里待多久 asks about plans, a natural next question.","fr":"计划在这里待多久 demande les projets, une question naturelle à la suite."},"audio":"/audio/small-talk/line-06.mp3"},{"id":"small-talk-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我打算待两个星期。很高兴和你聊天。","pinyin":"Wǒ dǎsuàn dāi liǎng gè xīngqī. Hěn gāoxìng hé nǐ liáotiān.","translation":{"en":"I plan to stay for two weeks. It was nice chatting with you.","fr":"Je compte rester deux semaines. J’ai été ravi de discuter avec vous."},"explanation":{"en":"和你聊天 means chatting with you, a warm way to end the talk.","fr":"和你聊天 signifie discuter avec vous, une façon chaleureuse de terminer."},"audio":"/audio/small-talk/line-07.mp3"},{"id":"small-talk-line-08","speaker":{"en":"Friend","fr":"Ami"},"hanzi":"好，祝你玩得开心！再见！","pinyin":"Hǎo, zhù nǐ wán de kāixīn! Zàijiàn!","translation":{"en":"Great, enjoy your stay! Goodbye!","fr":"Super, profitez bien de votre séjour ! Au revoir !"},"explanation":{"en":"祝 you 玩得开心 wishes someone a good time before saying 再见.","fr":"祝 vous souhaite 玩得开心 avant de dire 再见."},"audio":"/audio/small-talk/line-08.mp3"}]}', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(136, 'small-talk', 'dialogue', '{"title":{"en":"A friendly chat","fr":"Une conversation amicale"},"lines":[{"id":"small-talk-line-01","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"你好！很高兴认识你。","pinyin":"Nǐ hǎo! Hěn gāoxìng rènshi nǐ.","translation":{"en":"Hello! Nice to meet you.","fr":"Bonjour ! Enchanté de faire votre connaissance."},"explanation":{"en":"Open the chat with a friendly greeting and 很高兴认识你.","fr":"Ouvrez la conversation avec une salutation amicale et 很高兴认识你."},"audio":"/audio/small-talk/line-01.mp3"},{"id":"small-talk-line-02","speaker":{"en":"Friend","fr":"Ami"},"hanzi":"你好！你是哪里人？","pinyin":"Nǐ hǎo! Nǐ shì nǎlǐ rén?","translation":{"en":"Hello! Where are you from?","fr":"Bonjour ! D’où venez-vous ?"},"explanation":{"en":"你是哪里人 is the classic small-talk question about where someone is from.","fr":"你是哪里人 est la question classique de petite conversation sur l’origine de quelqu’un."},"audio":"/audio/small-talk/line-02.mp3"},{"id":"small-talk-line-03","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我是法国人。你是本地人吗？","pinyin":"Wǒ shì Fǎguó rén. Nǐ shì běndì rén ma?","translation":{"en":"I am French. Are you local?","fr":"Je suis français. Êtes-vous d’ici ?"},"explanation":{"en":"我是…人 states your nationality, and …吗 turns the next sentence into a question.","fr":"我是…人 indique votre nationalité, et …吗 transforme la phrase en question."},"audio":"/audio/small-talk/line-03.mp3"},{"id":"small-talk-line-04","speaker":{"en":"Friend","fr":"Ami"},"hanzi":"是的，我是上海人。这里的天气怎么样？","pinyin":"Shì de, wǒ shì Shànghǎi rén. Zhèlǐ de tiānqì zěnme yàng?","translation":{"en":"Yes, I am from Shanghai. How is the weather here?","fr":"Oui, je suis de Shanghai. Quel temps fait-il ici ?"},"explanation":{"en":"天气怎么样 asks about the weather, a safe topic for small talk.","fr":"天气怎么样 demande le temps qu’il fait, un sujet sûr pour la petite conversation."},"audio":"/audio/small-talk/line-04.mp3"},{"id":"small-talk-line-05","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"天气很好！你们这里的东西很好吃。","pinyin":"Tiānqì hěn hǎo! Nǐmen zhèlǐ de dōngxi hěn hǎochī.","translation":{"en":"The weather is great! The food here is delicious.","fr":"Il fait beau ! La nourriture ici est délicieuse."},"explanation":{"en":"Complement the weather and local food to keep the chat going.","fr":"Complimentez le temps et la cuisine locale pour poursuivre la conversation."},"audio":"/audio/small-talk/line-05.mp3"},{"id":"small-talk-line-06","speaker":{"en":"Friend","fr":"Ami"},"hanzi":"你计划在这里待多久？","pinyin":"Nǐ jìhuà zài zhèlǐ dāi duōjiǔ?","translation":{"en":"How long do you plan to stay here?","fr":"Combien de temps comptez-vous rester ici ?"},"explanation":{"en":"计划在这里待多久 asks about plans, a natural next question.","fr":"计划在这里待多久 demande les projets, une question naturelle à la suite."},"audio":"/audio/small-talk/line-06.mp3"},{"id":"small-talk-line-07","speaker":{"en":"Traveler","fr":"Voyageur"},"hanzi":"我打算待两个星期。很高兴和你聊天。","pinyin":"Wǒ dǎsuàn dāi liǎng gè xīngqī. Hěn gāoxìng hé nǐ liáotiān.","translation":{"en":"I plan to stay for two weeks. It was nice chatting with you.","fr":"Je compte rester deux semaines. J’ai été ravi de discuter avec vous."},"explanation":{"en":"和你聊天 means chatting with you, a warm way to end the talk.","fr":"和你聊天 signifie discuter avec vous, une façon chaleureuse de terminer."},"audio":"/audio/small-talk/line-07.mp3"},{"id":"small-talk-line-08","speaker":{"en":"Friend","fr":"Ami"},"hanzi":"好，祝你玩得开心！再见！","pinyin":"Hǎo, zhù nǐ wán de kāixīn! Zàijiàn!","translation":{"en":"Great, enjoy your stay! Goodbye!","fr":"Super, profitez bien de votre séjour ! Au revoir !"},"explanation":{"en":"祝 you 玩得开心 wishes someone a good time before saying 再见.","fr":"祝 vous souhaite 玩得开心 avant de dire 再见."},"audio":"/audio/small-talk/line-08.mp3"}]}', 'draft', 135, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(137, 'small-talk', 'sentencePatterns', '[{"id":"small-talk-pattern-1","pattern":"今天天气……。","meaning":{"en":"The weather is ... today.","fr":"Le temps est ... aujourd’hui."},"example":"今天天气很好。","audio":"/audio/small-talk/pattern-01.mp3","explanation":{"en":"Open a chat with 今天天气 and a word like 很好.","fr":"Ouvre une conversation avec 今天天气 et un mot comme 很好."}},{"id":"small-talk-pattern-2","pattern":"你好吗？","meaning":{"en":"How are you?","fr":"Comment vas-tu ?"},"example":"你好吗？","audio":"/audio/small-talk/pattern-02.mp3","explanation":{"en":"The classic way to ask how someone is doing.","fr":"La façon classique de demander comment ça va."}},{"id":"small-talk-pattern-3","pattern":"你从哪里来的？","meaning":{"en":"Where are you from?","fr":"D’où viens-tu ?"},"example":"你从哪里来的？","audio":"/audio/small-talk/pattern-03.mp3","explanation":{"en":"A friendly question about where someone comes from.","fr":"Une question amicale sur l’origine de quelqu’un."}},{"id":"small-talk-pattern-4","pattern":"你太……了！","meaning":{"en":"You are so ...!","fr":"Tu es vraiment ... !"},"example":"你太棒了！","audio":"/audio/small-talk/pattern-04.mp3","explanation":{"en":"Use 你太……了 to give a strong compliment.","fr":"Utilise 你太……了 pour faire un grand compliment."}},{"id":"small-talk-pattern-5","pattern":"你的……很好！","meaning":{"en":"Your ... is great!","fr":"Ton ... est superbe !"},"example":"你的皮肤很好！","audio":"/audio/small-talk/pattern-05.mp3","explanation":{"en":"Compliment a trait or feature with 你的……很好.","fr":"Complimente un trait avec 你的……很好."}},{"id":"small-talk-pattern-6","pattern":"今天天气好冷啊。","meaning":{"en":"The weather is cold today.","fr":"Il fait froid aujourd''hui."},"example":"今天天气好冷啊。","audio":"/audio/small-talk/pattern-06.mp3","explanation":{"en":"Comment on the cold weather with 好冷啊 to keep a chat going.","fr":"Commente le froid avec 好冷啊 pour poursuivre une conversation."}},{"id":"small-talk-pattern-7","pattern":"你穿衣真好看。","meaning":{"en":"I like your outfit.","fr":"J''aime beaucoup ta tenue."},"example":"你穿衣真好看。","audio":"/audio/small-talk/pattern-07.mp3","explanation":{"en":"Compliment someone''s outfit with 你穿衣真好看.","fr":"Complimente la tenue de quelqu''un avec 你穿衣真好看."}},{"id":"small-talk-pattern-8","pattern":"你太幽默了。","meaning":{"en":"You are so funny.","fr":"Tu es très drôle."},"example":"你太幽默了。","audio":"/audio/small-talk/pattern-08.mp3","explanation":{"en":"Compliment someone''s humor with 你太幽默了.","fr":"Complimente l''humour de quelqu''un avec 你太幽默了."}},{"id":"small-talk-pattern-9","pattern":"你真了不起！","meaning":{"en":"You are incredible!","fr":"Tu es incroyable !"},"example":"你真了不起！","audio":"/audio/small-talk/pattern-09.mp3","explanation":{"en":"Give a strong compliment with 你真了不起.","fr":"Fais un grand compliment avec 你真了不起."}},{"id":"small-talk-pattern-10","pattern":"你太热情了。","meaning":{"en":"You are so warm-hearted.","fr":"Tu es très chaleureux."},"example":"你太热情了。","audio":"/audio/small-talk/pattern-10.mp3","explanation":{"en":"Compliment someone''s warm personality with 你太热情了.","fr":"Complimente la chaleur de quelqu''un avec 你太热情了."}},{"id":"small-talk-pattern-11","pattern":"你太乐于助人了。","meaning":{"en":"You are kind-hearted and helpful.","fr":"Tu es gentil(le) et serviable."},"example":"你太乐于助人了。","audio":"/audio/small-talk/pattern-11.mp3","explanation":{"en":"Thank someone for being helpful with 你太乐于助人了.","fr":"Remercie quelqu''un d''être serviable avec 你太乐于助人了."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
(138, 'small-talk', 'sentencePatterns', '[{"id":"small-talk-pattern-1","pattern":"今天天气……。","meaning":{"en":"The weather is ... today.","fr":"Le temps est ... aujourd’hui."},"example":"今天天气很好。","audio":"/audio/small-talk/pattern-01.mp3","explanation":{"en":"Open a chat with 今天天气 and a word like 很好.","fr":"Ouvre une conversation avec 今天天气 et un mot comme 很好."}},{"id":"small-talk-pattern-2","pattern":"你好吗？","meaning":{"en":"How are you?","fr":"Comment vas-tu ?"},"example":"你好吗？","audio":"/audio/small-talk/pattern-02.mp3","explanation":{"en":"The classic way to ask how someone is doing.","fr":"La façon classique de demander comment ça va."}},{"id":"small-talk-pattern-3","pattern":"你从哪里来的？","meaning":{"en":"Where are you from?","fr":"D’où viens-tu ?"},"example":"你从哪里来的？","audio":"/audio/small-talk/pattern-03.mp3","explanation":{"en":"A friendly question about where someone comes from.","fr":"Une question amicale sur l’origine de quelqu’un."}},{"id":"small-talk-pattern-4","pattern":"你太……了！","meaning":{"en":"You are so ...!","fr":"Tu es vraiment ... !"},"example":"你太棒了！","audio":"/audio/small-talk/pattern-04.mp3","explanation":{"en":"Use 你太……了 to give a strong compliment.","fr":"Utilise 你太……了 pour faire un grand compliment."}},{"id":"small-talk-pattern-5","pattern":"你的……很好！","meaning":{"en":"Your ... is great!","fr":"Ton ... est superbe !"},"example":"你的皮肤很好！","audio":"/audio/small-talk/pattern-05.mp3","explanation":{"en":"Compliment a trait or feature with 你的……很好.","fr":"Complimente un trait avec 你的……很好."}},{"id":"small-talk-pattern-6","pattern":"今天天气好冷啊。","meaning":{"en":"The weather is cold today.","fr":"Il fait froid aujourd''hui."},"example":"今天天气好冷啊。","audio":"/audio/small-talk/pattern-06.mp3","explanation":{"en":"Comment on the cold weather with 好冷啊 to keep a chat going.","fr":"Commente le froid avec 好冷啊 pour poursuivre une conversation."}},{"id":"small-talk-pattern-7","pattern":"你穿衣真好看。","meaning":{"en":"I like your outfit.","fr":"J''aime beaucoup ta tenue."},"example":"你穿衣真好看。","audio":"/audio/small-talk/pattern-07.mp3","explanation":{"en":"Compliment someone''s outfit with 你穿衣真好看.","fr":"Complimente la tenue de quelqu''un avec 你穿衣真好看."}},{"id":"small-talk-pattern-8","pattern":"你太幽默了。","meaning":{"en":"You are so funny.","fr":"Tu es très drôle."},"example":"你太幽默了。","audio":"/audio/small-talk/pattern-08.mp3","explanation":{"en":"Compliment someone''s humor with 你太幽默了.","fr":"Complimente l''humour de quelqu''un avec 你太幽默了."}},{"id":"small-talk-pattern-9","pattern":"你真了不起！","meaning":{"en":"You are incredible!","fr":"Tu es incroyable !"},"example":"你真了不起！","audio":"/audio/small-talk/pattern-09.mp3","explanation":{"en":"Give a strong compliment with 你真了不起.","fr":"Fais un grand compliment avec 你真了不起."}},{"id":"small-talk-pattern-10","pattern":"你太热情了。","meaning":{"en":"You are so warm-hearted.","fr":"Tu es très chaleureux."},"example":"你太热情了。","audio":"/audio/small-talk/pattern-10.mp3","explanation":{"en":"Compliment someone''s warm personality with 你太热情了.","fr":"Complimente la chaleur de quelqu''un avec 你太热情了."}},{"id":"small-talk-pattern-11","pattern":"你太乐于助人了。","meaning":{"en":"You are kind-hearted and helpful.","fr":"Tu es gentil(le) et serviable."},"example":"你太乐于助人了。","audio":"/audio/small-talk/pattern-11.mp3","explanation":{"en":"Thank someone for being helpful with 你太乐于助人了.","fr":"Remercie quelqu''un d''être serviable avec 你太乐于助人了."}}]', 'draft', 137, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial editable draft copied from the published baseline.'),
(139, 'small-talk', 'vocabulary', '[{"id":"small-talk-vocab-1","hanzi":"哪里人","pinyin":"nǎlǐ rén","audio":"/audio/small-talk/vocab-01.mp3","meaning":{"en":"where someone is from","fr":"d’où vient quelqu’un"},"explanation":{"en":"Used in 你是哪里人 to ask about origin.","fr":"Utilisé dans 你是哪里人 pour demander l’origine."}},{"id":"small-talk-vocab-2","hanzi":"本地","pinyin":"běndì","audio":"/audio/small-talk/vocab-02.mp3","meaning":{"en":"local","fr":"local / d’ici"},"explanation":{"en":"本地人 means a local person.","fr":"本地人 signifie une personne d’ici."}},{"id":"small-talk-vocab-3","hanzi":"天气","pinyin":"tiānqì","audio":"/audio/small-talk/vocab-03.mp3","meaning":{"en":"weather","fr":"temps / météo"},"explanation":{"en":"A safe small-talk topic, often asked with 怎么样.","fr":"Un sujet sûr de conversation, souvent demandé avec 怎么样."}},{"id":"small-talk-vocab-4","hanzi":"好吃","pinyin":"hǎochī","audio":"/audio/small-talk/vocab-04.mp3","meaning":{"en":"delicious","fr":"délicieux"},"explanation":{"en":"Compliment food with 好吃.","fr":"Complimentez la nourriture avec 好吃."}},{"id":"small-talk-vocab-5","hanzi":"计划","pinyin":"jìhuà","audio":"/audio/small-talk/vocab-05.mp3","meaning":{"en":"plan","fr":"projet / prévoir"},"explanation":{"en":"计划 combines with 打算 to talk about plans.","fr":"计划 se combine avec 打算 pour parler des projets."}},{"id":"small-talk-vocab-6","hanzi":"待","pinyin":"dāi","audio":"/audio/small-talk/vocab-06.mp3","meaning":{"en":"to stay","fr":"rester"},"explanation":{"en":"待 is used to say how long you will stay.","fr":"待 s’utilise pour dire combien de temps vous restez."}},{"id":"small-talk-vocab-7","hanzi":"聊天","pinyin":"liáotiān","audio":"/audio/small-talk/vocab-07.mp3","meaning":{"en":"to chat","fr":"discuter"},"explanation":{"en":"聊天 is the word for casual chatting.","fr":"聊天 est le mot pour une discussion informelle."}},{"id":"small-talk-vocab-8","hanzi":"祝你","pinyin":"zhù nǐ","audio":"/audio/small-talk/vocab-08.mp3","meaning":{"en":"wish you","fr":"je te souhaite"},"explanation":{"en":"祝你 starts a good wish for the other person.","fr":"祝你 introduit un bon souhait pour l’autre personne."}},{"id":"small-talk-vocab-9","hanzi":"开心","pinyin":"kāixīn","audio":"/audio/small-talk/vocab-09.mp3","meaning":{"en":"happy","fr":"joyeux / heureux"},"explanation":{"en":"玩得开心 means have fun.","fr":"玩得开心 signifie amuse-toi bien."}},{"id":"small-talk-vocab-10","hanzi":"上海","pinyin":"Shànghǎi","audio":"/audio/small-talk/vocab-10.mp3","meaning":{"en":"Shanghai","fr":"Shanghai"},"explanation":{"en":"A common city name to practice saying where you or others are from.","fr":"Un nom de ville courant pour pratiquer l’origine."}}]', 'published', null, 'seed:static-content', '2026-07-26T00:00:00.000Z', 'Initial published content imported from static lesson source.'),
